window.GITA=window.GITA||{};GITA.capitulos=GITA.capitulos||{};GITA.capitulos[7]={"numero": 7, "titulo": "El yoga del conocimiento y del conocimiento realizado", "versos": [{"n": 1, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "मय्यासक्तमनाः पार्थ योगं युञ्जन्मदाश्रयः ।", "असंशयं समग्रं मां यथा ज्ञास्यसि तच्छृणु ॥१॥"], "iast": ["śrī-bhagavān uvāca", "mayy āsakta-manāḥ pārtha yogaṃ yuñjan mad-āśrayaḥ", "asaṃśayaṃ samagraṃ māṃ yathā jñāsyasi tac chṛṇu"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Escucha, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, cómo, con la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> apegada a mí, practicando el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> y refugiado en mí, me conocerás por entero y sin <a class=\"t\" href=\"glosario.html#samsaya\" data-t=\"samsaya\">duda</a>.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (gloria) + bhagavat (el Señor)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg. pron.", "es": "en mí"}, {"iast": "āsakta-manāḥ", "sa": "आसक्तमनाः", "gram": "nom. sg. m. comp.", "es": "con la mente apegada", "ref": "manas", "analisis": "āsakta (apegado, adherido) + manas (mente): bahuvrīhi"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "yogam", "sa": "योगम्", "gram": "ac. sg. m.", "es": "el yoga", "ref": "yoga"}, {"iast": "yuñjan", "sa": "युञ्जन्", "gram": "nom. sg. m. part. pres.", "es": "practicando", "analisis": "√yuj (uncir, aplicarse)"}, {"iast": "mad-āśrayaḥ", "sa": "मदाश्रयः", "gram": "nom. sg. m. comp.", "es": "refugiado en mí", "ref": "prapatti", "analisis": "mad (yo) + āśraya (refugio, apoyo): «el que me tiene por refugio»"}, {"iast": "asaṃśayam", "sa": "असंशयम्", "gram": "ac. sg. m. adj.", "es": "sin duda", "ref": "samsaya", "analisis": "a (sin) + saṃśaya (duda)"}, {"iast": "samagram", "sa": "समग्रम्", "gram": "ac. sg. m. adj.", "es": "por entero", "analisis": "sam + agra: «completo, entero»"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "yathā", "sa": "यथा", "gram": "ind.", "es": "cómo"}, {"iast": "jñāsyasi", "sa": "ज्ञास्यसि", "gram": "2 sg. fut. act.", "es": "conocerás", "analisis": "√jñā (conocer)"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "eso"}, {"iast": "śṛṇu", "sa": "शृणु", "gram": "2 sg. impv. act.", "es": "escucha", "analisis": "√śru (oír)"}], "nota": "<p>El capítulo cambia de objeto. El sexto terminaba con el yogui que adora a Kṛṣṇa con fe (<a class=\"vref\" href=\"capitulo-06.html#v47\" data-v=\"6.47\">6.47</a>); el séptimo enseña a conocer a aquel a quien se adora. <em>Samagram</em>, «entero, completo», anuncia el programa: no sólo lo que Kṛṣṇa es en sí mismo, sino también lo que es en el mundo, que los versos siguientes irán mostrando. <em>Mad-āśraya</em>, «el que me tiene por refugio», es la primera aparición en el capítulo de una idea que volverá en <a class=\"vref\" href=\"capitulo-07.html#v14\" data-v=\"7.14\">7.14</a> y en <a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a>: refugiarse en Kṛṣṇa.</p>", "interp": [{"titulo": "Empieza la segunda parte", "html": "<p>La tradición divide la Gītā en tres grupos de seis capítulos, y el séptimo abre el segundo: el de la devoción, según Yāmuna y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>; el que trata del Señor mismo, según <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> y <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>. El verso hace el puente: retoma del capítulo 6 la práctica del yoga (<em>yogaṃ yuñjan</em>), pero la orienta hacia Kṛṣṇa, con la mente «apegada a mí». El apego, que la Gītā pide abandonar en todo lo demás, se vuelve aquí el medio, cuando su objeto es él.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 2, "hablante": "krsna", "sa": ["ज्ञानं तेऽहं सविज्ञानमिदं वक्ष्याम्यशेषतः ।", "यज्ज्ञात्वा नेह भूयोऽन्यज्ज्ञातव्यमवशिष्यते ॥२॥"], "iast": ["jñānaṃ te 'haṃ sa-vijñānam idaṃ vakṣyāmy aśeṣataḥ", "yaj jñātvā neha bhūyo 'nyaj jñātavyam avaśiṣyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Te enseñaré por completo este <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>, junto con el <a class=\"t\" href=\"glosario.html#vijnana\" data-t=\"vijnana\">conocimiento realizado</a>; una vez sabido, no queda aquí nada más por saber.</span>", "palabras": [{"iast": "jñānam", "sa": "ज्ञानम्", "gram": "ac. sg. n.", "es": "el conocimiento", "ref": "jnana", "analisis": "√jñā (conocer)"}, {"iast": "te", "sa": "ते", "gram": "dat. sg. pron.", "es": "a ti"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "sa-vijñānam", "sa": "सविज्ञानम्", "gram": "ac. sg. n. comp.", "es": "junto con el conocimiento realizado", "ref": "vijnana", "analisis": "sa (con) + vijñāna (conocimiento realizado, discernimiento)"}, {"iast": "idam", "sa": "इदम्", "gram": "ac. sg. n. pron.", "es": "este"}, {"iast": "vakṣyāmi", "sa": "वक्ष्यामि", "gram": "1 sg. fut. act.", "es": "enseñaré", "analisis": "√vac (decir)"}, {"iast": "aśeṣataḥ", "sa": "अशेषतः", "gram": "adv.", "es": "por completo", "analisis": "a (sin) + śeṣa (resto): «sin dejar resto»"}, {"iast": "yat", "sa": "यत्", "gram": "ac. sg. n. rel.", "es": "lo cual"}, {"iast": "jñātvā", "sa": "ज्ञात्वा", "gram": "abs.", "es": "una vez sabido", "analisis": "√jñā (conocer)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí"}, {"iast": "bhūyaḥ", "sa": "भूयः", "gram": "ind.", "es": "más"}, {"iast": "anyat", "sa": "अन्यत्", "gram": "nom. sg. n. pron.", "es": "otra cosa"}, {"iast": "jñātavyam", "sa": "ज्ञातव्यम्", "gram": "nom. sg. n. gerundivo", "es": "por saber", "analisis": "√jñā (conocer): «lo que ha de saberse»"}, {"iast": "avaśiṣyate", "sa": "अवशिष्यते", "gram": "3 sg. pres. pas.", "es": "queda", "analisis": "ava-√śiṣ (dejar), pasiva: «es dejado, resta»"}], "nota": "<p><em>Jñāna</em> y <em>vijñāna</em> van juntos también en <a class=\"vref\" href=\"capitulo-03.html#v41\" data-v=\"3.41\">3.41</a>, <a class=\"vref\" href=\"capitulo-06.html#v8\" data-v=\"6.8\">6.8</a>, <a class=\"vref\" href=\"capitulo-09.html#v1\" data-v=\"9.1\">9.1</a> y <a class=\"vref\" href=\"capitulo-18.html#v42\" data-v=\"18.42\">18.42</a>, y dan nombre al capítulo (<em>Jñāna-vijñāna-yoga</em>). El prefijo <em>vi-</em> puede indicar distinción o intensidad, y de ahí las dos lecturas de las alternativas. Esta edición traduce «conocimiento realizado», que conserva la idea de un saber que ha pasado de la enseñanza a la experiencia sin excluir la otra. <em>Iha</em>, «aquí», puede ser «en este mundo» o «en este camino».</p>", "interp": [{"titulo": "Un saber que agota lo que hay que saber", "html": "<p>La promesa es audaz: tras este conocimiento «no queda nada más por saber». La Muṇḍaka Upaniṣad formula una pregunta parecida —qué es aquello que, conocido, hace conocido todo lo demás— y la Gītā responde a su modo: lo que hay que conocer es a Kṛṣṇa, porque todo procede de él (<a class=\"vref\" href=\"capitulo-07.html#v6\" data-v=\"7.6\">7.6</a>–<a class=\"vref\" href=\"capitulo-07.html#v7\" data-v=\"7.7\">7.7</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Te enseñaré por completo este conocimiento, junto con su experiencia directa; una vez sabido, no queda aquí nada más por saber.", "nota": "<p>Si <em>vijñāna</em> se entiende como el conocimiento hecho experiencia propia: <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> glosa <em>savijñānam</em> como «unido a la experiencia propia» (<em>svānubhava-yuktam</em>). <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> lo contrapone expresamente al conocimiento que viene de las escrituras (<em>jñānaṃ śāstrīyam, vijñānam anubhavaḥ</em>), y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo entiende como el conocimiento directo que nace cuando madura la reflexión.</p>"}, {"html": "Te enseñaré por completo este conocimiento, junto con el conocimiento que discierne; una vez sabido, no queda aquí nada más por saber.", "nota": "<p>Si <em>vijñāna</em> se entiende, con el prefijo <em>vi-</em> en su sentido de distinción, como el conocimiento que distingue: para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, el de Kṛṣṇa en cuanto diferente de todo lo demás, por estar libre de todo mal y lleno de cualidades sin límite; para <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, el conocimiento particular (<em>viśeṣa-jñāna</em>) de sus manifestaciones, el que empieza con «yo soy el sabor en las aguas» (<a class=\"vref\" href=\"capitulo-07.html#v8\" data-v=\"7.8\">7.8</a>).</p>"}]}, {"n": 3, "hablante": "krsna", "sa": ["मनुष्याणां सहस्रेषु कश्चिद्यतति सिद्धये ।", "यततामपि सिद्धानां कश्चिन्मां वेत्ति तत्त्वतः ॥३॥"], "iast": ["manuṣyāṇāṃ sahasreṣu kaścid yatati siddhaye", "yatatām api siddhānāṃ kaścin māṃ vetti tattvataḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Entre miles de hombres, apenas uno se esfuerza por alcanzar la perfección; y aun entre los que se esfuerzan y la han alcanzado, apenas uno me conoce de verdad.</span>", "palabras": [{"iast": "manuṣyāṇām", "sa": "मनुष्याणाम्", "gram": "gen. pl. m.", "es": "de los hombres"}, {"iast": "sahasreṣu", "sa": "सहस्रेषु", "gram": "loc. pl. n.", "es": "entre miles"}, {"iast": "kaścit", "sa": "कश्चित्", "gram": "nom. sg. m. pron.", "es": "alguno, apenas uno"}, {"iast": "yatati", "sa": "यतति", "gram": "3 sg. pres. act.", "es": "se esfuerza", "analisis": "√yat (esforzarse)"}, {"iast": "siddhaye", "sa": "सिद्धये", "gram": "dat. sg. f.", "es": "por la perfección", "analisis": "siddhi (logro, perfección), de √sidh (cumplirse)"}, {"iast": "yatatām", "sa": "यतताम्", "gram": "gen. pl. m. part. pres.", "es": "de los que se esfuerzan", "analisis": "√yat (esforzarse)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun"}, {"iast": "siddhānām", "sa": "सिद्धानाम्", "gram": "gen. pl. m. ppp", "es": "de los perfectos", "analisis": "siddha (cumplido, perfecto), de √sidh"}, {"iast": "kaścit", "sa": "कश्चित्", "gram": "nom. sg. m. pron.", "es": "apenas uno"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "vetti", "sa": "वेत्ति", "gram": "3 sg. pres. act.", "es": "conoce", "analisis": "√vid (saber)"}, {"iast": "tattvataḥ", "sa": "तत्त्वतः", "gram": "adv.", "es": "de verdad, tal como soy", "analisis": "tattva (la realidad, «el ser-eso») + -tas"}], "nota": "<p><em>Kaścit</em>, «alguno», tiene aquí el valor de «apenas uno, raro». <em>Tattvataḥ</em>, «según la realidad», es conocer a Kṛṣṇa tal como es, no según la idea que cada uno se hace de él; el capítulo volverá sobre esa rareza en <a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a>: «difícil de encontrar es esa gran alma».</p>", "interp": [{"titulo": "Una pirámide que se estrecha", "html": "<p>El verso dibuja una selección en dos pasos: de los muchos, pocos se esfuerzan; de los que se esfuerzan, pocos llegan a conocerlo. No es un juicio de desprecio, sino una advertencia sobre la dificultad de lo que se va a enseñar, y prepara la clasificación de los devotos de <a class=\"vref\" href=\"capitulo-07.html#v16\" data-v=\"7.16\">7.16</a>–<a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a>.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Entre miles de hombres, apenas uno se esfuerza por alcanzar la perfección; y entre esos que se esfuerzan, que merecen ya el nombre de perfectos, apenas uno me conoce de verdad.", "nota": "<p>Tomando <em>yatatām siddhānām</em> como una sola expresión: los «perfectos» no son otro grupo, sino los mismos que se esfuerzan, a los que se llama así por su empeño en la liberación. Es la lectura de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>: «perfectos son, en efecto, los que se esfuerzan por la liberación». <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> también ve un solo grupo, aunque llama «perfectos» a los que traen méritos de vidas anteriores; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, en cambio, distinguen varios escalones.</p>"}]}, {"n": 4, "hablante": "krsna", "sa": ["भूमिरापोऽनलो वायुः खं मनो बुद्धिरेव च ।", "अहङ्कार इतीयं मे भिन्ना प्रकृतिरष्टधा ॥४॥"], "iast": ["bhūmir āpo 'nalo vāyuḥ khaṃ mano buddhir eva ca", "ahaṃkāra itīyaṃ me bhinnā prakṛtir aṣṭadhā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\"><a class=\"t\" href=\"glosario.html#mahabhuta\" data-t=\"mahabhuta\">Tierra, agua, fuego, aire, espacio</a>, <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a>, <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> y <a class=\"t\" href=\"glosario.html#ahankara\" data-t=\"ahankara\">sentido del yo</a>: ésta es mi <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a>, dividida en ocho partes.</span>", "palabras": [{"iast": "bhūmiḥ", "sa": "भूमिः", "gram": "nom. sg. f.", "es": "la tierra", "ref": "mahabhuta"}, {"iast": "āpaḥ", "sa": "आपः", "gram": "nom. pl. f.", "es": "el agua", "ref": "mahabhuta", "analisis": "ap (agua), siempre en plural"}, {"iast": "analaḥ", "sa": "अनलः", "gram": "nom. sg. m.", "es": "el fuego", "ref": "mahabhuta"}, {"iast": "vāyuḥ", "sa": "वायुः", "gram": "nom. sg. m.", "es": "el aire", "ref": "mahabhuta"}, {"iast": "kham", "sa": "खम्", "gram": "nom. sg. n.", "es": "el espacio", "ref": "mahabhuta", "analisis": "kha (hueco, cielo): sinónimo de ākāśa"}, {"iast": "manaḥ", "sa": "मनः", "gram": "nom. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "buddhiḥ", "sa": "बुद्धिः", "gram": "nom. sg. f.", "es": "el entendimiento", "ref": "buddhi"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "también"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "ahaṃkāraḥ", "sa": "अहङ्कारः", "gram": "nom. sg. m.", "es": "el sentido del yo", "ref": "ahankara", "analisis": "aham (yo) + kāra (hacer)"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así"}, {"iast": "iyam", "sa": "इयम्", "gram": "nom. sg. f. pron.", "es": "ésta"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mía"}, {"iast": "bhinnā", "sa": "भिन्ना", "gram": "nom. sg. f. ppp", "es": "dividida", "analisis": "√bhid (partir)"}, {"iast": "prakṛtiḥ", "sa": "प्रकृतिः", "gram": "nom. sg. f.", "es": "la naturaleza", "ref": "prakrti"}, {"iast": "aṣṭadhā", "sa": "अष्टधा", "gram": "adv.", "es": "en ocho partes", "analisis": "aṣṭa (ocho) + -dhā (de tantas maneras)"}], "nota": "<p>Los cinco primeros son los grandes elementos (<em>mahābhūta</em>); los tres últimos, las facultades internas. <em>Kha</em> es el espacio vacío, el <em>ākāśa</em>, que muchas traducciones llaman «éter», el elemento del que es propio el sonido (<a class=\"vref\" href=\"capitulo-07.html#v8\" data-v=\"7.8\">7.8</a>). La lista recuerda la del Sāṅkhya, que deriva de la naturaleza primordial el entendimiento, el sentido del yo, la mente y los elementos; en <a class=\"vref\" href=\"capitulo-13.html#v5\" data-v=\"13.5\">13.5</a> la Gītā dará una enumeración más larga del «campo».</p>", "interp": [{"titulo": "Cada término nombra su causa", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> no lee la lista como una enumeración de cosas visibles: la tierra no es la tierra burda, sino su elemento sutil (<em>tanmātra</em>), y lo mismo el agua, el fuego, el aire y el espacio. Los tres últimos términos nombran cada uno un eslabón más arriba en la cadena de las causas: «mente» designa su causa, el sentido del yo; «entendimiento», la causa de éste, el <em>mahat</em>; y «sentido del yo», lo no manifiesto unido a la ignorancia, la raíz de todo, que recibe ese nombre porque el sentido del yo es lo que impulsa toda actividad. Así los ocho términos recorren la naturaleza entera, de los elementos sutiles a su raíz. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, en su primera explicación, y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> leen de modo parecido; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> toma los términos en su sentido directo: los elementos, los sentidos encabezados por la mente, el <em>mahat</em> y el <em>ahaṃkāra</em>. Jayatīrtha, el comentarista de <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, rechaza expresamente la glosa de Śaṅkara.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La huella del Sāṅkhya", "html": "<p>Los ocho términos son una versión abreviada de las categorías (<em>tattva</em>) del Sāṅkhya, que la tradición posterior fijará en veinticuatro, más el espíritu (<em>puruṣa</em>). La Gītā las usa, pero les cambia el sentido: no son una naturaleza autónoma frente al espíritu, sino «mi» naturaleza, la de Kṛṣṇa.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "las-dos-naturalezas"}, {"n": 5, "hablante": "krsna", "sa": ["अपरेयमितस्त्वन्यां प्रकृतिं विद्धि मे पराम् ।", "जीवभूतां महाबाहो ययेदं धार्यते जगत् ॥५॥"], "iast": ["apareyam itas tv anyāṃ prakṛtiṃ viddhi me parām", "jīva-bhūtāṃ mahā-bāho yayedaṃ dhāryate jagat"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Ésta es la inferior. Pero conoce, oh <a class=\"t\" href=\"glosario.html#mahabaho\" data-t=\"mahabaho\">Mahābāhu</a>, mi otra <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a>, la superior, la <a class=\"t\" href=\"glosario.html#jiva\" data-t=\"jiva\">viviente</a>, por la que se sostiene este mundo.</span>", "palabras": [{"iast": "aparā", "sa": "अपरा", "gram": "nom. sg. f. adj.", "es": "inferior", "analisis": "a (no) + para (superior)"}, {"iast": "iyam", "sa": "इयम्", "gram": "nom. sg. f. pron.", "es": "ésta"}, {"iast": "itaḥ", "sa": "इतः", "gram": "ind.", "es": "de ésta, distinta de ésta"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "anyām", "sa": "अन्याम्", "gram": "ac. sg. f. pron.", "es": "otra"}, {"iast": "prakṛtim", "sa": "प्रकृतिम्", "gram": "ac. sg. f.", "es": "naturaleza", "ref": "prakrti"}, {"iast": "viddhi", "sa": "विद्धि", "gram": "2 sg. impv. act.", "es": "conoce", "analisis": "√vid (saber)"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mía"}, {"iast": "parām", "sa": "पराम्", "gram": "ac. sg. f. adj.", "es": "superior"}, {"iast": "jīva-bhūtām", "sa": "जीवभूताम्", "gram": "ac. sg. f. comp.", "es": "la viviente, la que es vida", "ref": "jiva", "analisis": "jīva (vida, ser viviente) + bhūta (que es, hecho de)"}, {"iast": "mahā-bāho", "sa": "महाबाहो", "gram": "voc. sg. m. comp.", "es": "oh Mahābāhu", "ref": "mahabaho"}, {"iast": "yayā", "sa": "यया", "gram": "instr. sg. f. rel.", "es": "por la cual"}, {"iast": "idam", "sa": "इदम्", "gram": "nom. sg. n. pron.", "es": "este"}, {"iast": "dhāryate", "sa": "धार्यते", "gram": "3 sg. pres. pas.", "es": "se sostiene", "analisis": "√dhṛ (sostener), pasiva"}, {"iast": "jagat", "sa": "जगत्", "gram": "nom. sg. n.", "es": "el mundo", "analisis": "«lo que se mueve», de √gam (ir)"}], "nota": "<p><em>Aparā</em>, «no suprema, inferior», y <em>parā</em>, «suprema, superior», dividen la naturaleza de Kṛṣṇa en dos: la de <a class=\"vref\" href=\"capitulo-07.html#v4\" data-v=\"7.4\">7.4</a>, material y dividida en ocho, y otra que es vida y conciencia. El verbo <em>dhāryate</em>, «es sostenido», dice qué hace la superior: sin ella, la inferior no formaría un mundo vivo. La palabra <em>jīva-bhūta</em> volverá en <a class=\"vref\" href=\"capitulo-15.html#v7\" data-v=\"15.7\">15.7</a>, donde una parte eterna de Kṛṣṇa «se vuelve el ser viviente en el mundo de los vivos».</p>", "interp": [{"titulo": "Dos naturalezas, un solo dueño", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> las dos naturalezas son reales y distintas: la materia inconsciente y los sí-mismos conscientes. Las dos pertenecen al Señor, que es su sostén y su dueño, y por eso Kṛṣṇa las llama «mías». En su teología, el mundo y las almas son como el cuerpo del Señor, que es su alma.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Las energías del Señor", "html": "<p>La tradición gauḍīya lee las dos naturalezas como dos energías (<em>śakti</em>) de Kṛṣṇa: la material y la de los seres vivientes, que es superior porque es consciente. Prabhupāda traduce «energía superior», formada por las entidades vivientes que explotan los recursos de la naturaleza inferior.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Ésta es la inferior. Pero conoce, oh Mahābāhu, mi otra naturaleza, la superior, la que forman los seres vivientes, por la que se sostiene este mundo.", "nota": "<p>Si <em>jīva-bhūtā</em> se entiende como «hecha de <em>jīvas</em>»: la naturaleza superior es el conjunto de los sí-mismos individuales, conscientes, frente a la materia inconsciente de <a class=\"vref\" href=\"capitulo-07.html#v4\" data-v=\"7.4\">7.4</a>. Es la lectura de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>. No es la de todos los vaiṣṇavas: <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> ve en la naturaleza superior a Śrī, la consorte de Viṣṇu, consciente y eterna, que sostiene la vida de los seres.</p>"}, {"html": "Ésta es la inferior. Pero conoce, oh Mahābāhu, mi otra naturaleza, la superior, el principio de la vida, por la que se sostiene este mundo.", "nota": "<p>Si <em>jīva-bhūtā</em> se entiende como «la que es causa de que se sostenga la vida»: así la glosa <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, que la identifica con el conocedor del campo (<em>kṣetrajña</em>), la llama pura y «mi propio ser», y dice que sostiene el mundo habiendo entrado en él. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> la identifican también con el conocedor del campo.</p>"}], "ens": "las-dos-naturalezas"}, {"n": 6, "hablante": "krsna", "sa": ["एतद्योनीनि भूतानि सर्वाणीत्युपधारय ।", "अहं कृत्स्नस्य जगतः प्रभवः प्रलयस्तथा ॥६॥"], "iast": ["etad-yonīni bhūtāni sarvāṇīty upadhāraya", "ahaṃ kṛtsnasya jagataḥ prabhavaḥ pralayas tathā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Comprende que todos los seres tienen en estas dos su matriz: yo soy el origen del mundo entero, y también su disolución.</span>", "palabras": [{"iast": "etad-yonīni", "sa": "एतद्योनीनि", "gram": "nom. pl. n. comp.", "es": "que tienen en éstas su matriz", "analisis": "etad (esto, estas dos) + yoni (matriz, origen): bahuvrīhi"}, {"iast": "bhūtāni", "sa": "भूतानि", "gram": "nom. pl. n.", "es": "los seres"}, {"iast": "sarvāṇi", "sa": "सर्वाणि", "gram": "nom. pl. n. adj.", "es": "todos"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así"}, {"iast": "upadhāraya", "sa": "उपधारय", "gram": "2 sg. impv. act. caus.", "es": "comprende", "analisis": "upa-√dhṛ (sostener), causativo: «retén, ten presente»"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "kṛtsnasya", "sa": "कृत्स्नस्य", "gram": "gen. sg. n. adj.", "es": "entero"}, {"iast": "jagataḥ", "sa": "जगतः", "gram": "gen. sg. n.", "es": "del mundo"}, {"iast": "prabhavaḥ", "sa": "प्रभवः", "gram": "nom. sg. m.", "es": "el origen", "analisis": "pra-√bhū (surgir)"}, {"iast": "pralayaḥ", "sa": "प्रलयः", "gram": "nom. sg. m.", "es": "la disolución", "analisis": "pra-√lī (disolverse)"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "y también"}], "nota": "<p><em>Etad-yonīni</em>, «que tienen esto por matriz»: el pronombre remite a las dos naturalezas de los versos anteriores, la inferior y la superior. <em>Yoni</em> es la matriz, el seno que da a luz; la imagen volverá en <a class=\"vref\" href=\"capitulo-14.html#v3\" data-v=\"14.3\">14.3</a>–<a class=\"vref\" href=\"capitulo-14.html#v4\" data-v=\"14.4\">14.4</a>, donde Kṛṣṇa deposita la semilla en el gran brahman, su matriz, y se llama a sí mismo el padre que da la simiente. Lo que nace de las dos naturalezas nace, en último término, de él.</p>", "interp": [{"titulo": "Origen y fin", "html": "<p><em>Prabhava</em> y <em>pralaya</em>, el surgir y el disolverse, encierran entre los dos extremos todo lo que existe: Kṛṣṇa no es sólo el que pone el mundo en marcha, sino también aquel en quien acaba. El par volverá en <a class=\"vref\" href=\"capitulo-09.html#v18\" data-v=\"9.18\">9.18</a> y, como día y noche de Brahmā, en <a class=\"vref\" href=\"capitulo-08.html#v18\" data-v=\"8.18\">8.18</a>–<a class=\"vref\" href=\"capitulo-08.html#v19\" data-v=\"8.19\">8.19</a>.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "las-dos-naturalezas"}, {"n": 7, "hablante": "krsna", "sa": ["मत्तः परतरं नान्यत्किञ्चिदस्ति धनञ्जय ।", "मयि सर्वमिदं प्रोतं सूत्रे मणिगणा इव ॥७॥"], "iast": ["mattaḥ parataraṃ nānyat kiñcid asti dhanañjaya", "mayi sarvam idaṃ protaṃ sūtre maṇi-gaṇā iva"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">No hay nada más alto que yo, oh <a class=\"t\" href=\"glosario.html#dhananjaya\" data-t=\"dhananjaya\">Dhanañjaya</a>. Todo esto está ensartado en mí como las perlas en un hilo.</span>", "palabras": [{"iast": "mattaḥ", "sa": "मत्तः", "gram": "abl. sg. pron.", "es": "que yo"}, {"iast": "parataram", "sa": "परतरम्", "gram": "nom. sg. n. adj.", "es": "más alto", "analisis": "para (superior) + -tara (comparativo)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "anyat", "sa": "अन्यत्", "gram": "nom. sg. n. pron.", "es": "otra cosa"}, {"iast": "kiñcit", "sa": "किञ्चित्", "gram": "nom. sg. n. pron.", "es": "nada, algo"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres. act.", "es": "hay", "analisis": "√as (ser)"}, {"iast": "dhanañjaya", "sa": "धनञ्जय", "gram": "voc. sg. m.", "es": "oh Dhanañjaya", "ref": "dhananjaya"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg. pron.", "es": "en mí"}, {"iast": "sarvam", "sa": "सर्वम्", "gram": "nom. sg. n. adj.", "es": "todo"}, {"iast": "idam", "sa": "इदम्", "gram": "nom. sg. n. pron.", "es": "esto"}, {"iast": "protam", "sa": "प्रोतम्", "gram": "nom. sg. n. ppp", "es": "ensartado", "analisis": "pra-√vā (tejer), «tejido, ensartado»"}, {"iast": "sūtre", "sa": "सूत्रे", "gram": "loc. sg. n.", "es": "en un hilo"}, {"iast": "maṇi-gaṇāḥ", "sa": "मणिगणाः", "gram": "nom. pl. m. comp.", "es": "las cuentas, las perlas", "analisis": "maṇi (gema, cuenta) + gaṇa (conjunto, sarta)"}, {"iast": "iva", "sa": "इव", "gram": "ind.", "es": "como"}], "nota": "<p><em>Maṇi</em> es cualquier gema o cuenta; «perlas» es la imagen más reconocible en español. El hilo no se ve, pero sin él las cuentas no formarían un collar: así sostiene Kṛṣṇa el mundo sin ser una más de sus piezas. Los versos siguientes (<a class=\"vref\" href=\"capitulo-07.html#v8\" data-v=\"7.8\">7.8</a>–<a class=\"vref\" href=\"capitulo-07.html#v12\" data-v=\"7.12\">7.12</a>) recorren algunas de esas cuentas y muestran el hilo en cada una.</p>", "interp": [{"titulo": "El hilo y las cuentas", "html": "<p>La imagen del hilo (<em>sūtra</em>) que atraviesa y une los mundos tiene antecedentes en las Upaniṣads: en la Bṛhad-āraṇyaka, Uddālaka pregunta a Yājñavalkya por el hilo en que están ensartados este mundo, el otro y todos los seres, y por el que los gobierna desde dentro. La Gītā hace de Kṛṣṇa ese hilo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "No hay ninguna otra causa más alta que yo, oh Dhanañjaya. Todo esto está ensartado en mí como las perlas en un hilo.", "nota": "<p>Leyendo la primera mitad en el contexto del verso anterior, donde Kṛṣṇa se ha dicho origen y disolución del mundo: lo que no tiene nada por encima es la causa. Es la glosa de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>: «no hay ninguna otra causa (<em>kāraṇāntaram</em>) más alta que yo; yo soy la causa del mundo». <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> entiende lo mismo (no hay otra causa independiente de la creación y la disolución del mundo), y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> cuenta también el ser causa entre los títulos por los que nada es más alto que él.</p>"}], "ens": "ensartado-en-mi"}, {"n": 8, "hablante": "krsna", "sa": ["रसोऽहमप्सु कौन्तेय प्रभास्मि शशिसूर्ययोः ।", "प्रणवः सर्ववेदेषु शब्दः खे पौरुषं नृषु ॥८॥"], "iast": ["raso 'ham apsu kaunteya prabhāsmi śaśi-sūryayoḥ", "praṇavaḥ sarva-vedeṣu śabdaḥ khe pauruṣaṃ nṛṣu"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Yo soy el sabor en las aguas, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>, la luz de la luna y del sol; soy la sílaba <a class=\"t\" href=\"glosario.html#om\" data-t=\"om\">oṃ</a> en todos los <a class=\"t\" href=\"glosario.html#veda\" data-t=\"veda\">Vedas</a>, el sonido en el espacio, la hombría en los hombres.</span>", "palabras": [{"iast": "rasaḥ", "sa": "रसः", "gram": "nom. sg. m.", "es": "el sabor", "analisis": "también «jugo, savia, esencia»"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "apsu", "sa": "अप्सु", "gram": "loc. pl. f.", "es": "en las aguas", "analisis": "ap (agua), que se usa casi siempre en plural"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh Kaunteya", "ref": "kaunteya", "analisis": "«hijo de Kuntī»"}, {"iast": "prabhā", "sa": "प्रभा", "gram": "nom. sg. f.", "es": "la luz, el resplandor", "analisis": "pra-√bhā (brillar)"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres. act.", "es": "soy", "analisis": "√as (ser)"}, {"iast": "śaśi-sūryayoḥ", "sa": "शशिसूर्ययोः", "gram": "gen. du. m. comp.", "es": "de la luna y del sol", "ref": "surya", "analisis": "śaśin (la luna, «la que lleva la liebre») + sūrya (el sol)"}, {"iast": "praṇavaḥ", "sa": "प्रणवः", "gram": "nom. sg. m.", "es": "la sílaba oṃ", "ref": "om", "analisis": "de pra-√nu (resonar, aclamar): nombre de la sílaba oṃ"}, {"iast": "sarva-vedeṣu", "sa": "सर्ववेदेषु", "gram": "loc. pl. m. comp.", "es": "en todos los Vedas", "ref": "veda", "analisis": "sarva (todo) + veda"}, {"iast": "śabdaḥ", "sa": "शब्दः", "gram": "nom. sg. m.", "es": "el sonido"}, {"iast": "khe", "sa": "खे", "gram": "loc. sg. n.", "es": "en el espacio", "ref": "mahabhuta", "analisis": "kha (hueco, espacio), sinónimo de ākāśa, el primero de los elementos"}, {"iast": "pauruṣam", "sa": "पौरुषम्", "gram": "nom. sg. n.", "es": "la hombría", "analisis": "de puruṣa (varón, persona): lo propio del varón; también «esfuerzo, capacidad de obrar»"}, {"iast": "nṛṣu", "sa": "नृषु", "gram": "loc. pl. m.", "es": "en los hombres", "analisis": "nṛ (hombre, varón)"}], "nota": "<p><em>Praṇava</em>: nombre tradicional de la sílaba <em>oṃ</em>, la que «resuena» al comienzo y al final de la recitación védica (véase la ficha <a class=\"t\" href=\"glosario.html#om\" data-t=\"om\">oṃ</a>). <em>Kha</em>: «el hueco», el espacio o éter (<em>ākāśa</em>), el más sutil de los cinco <a class=\"t\" href=\"glosario.html#mahabhuta\" data-t=\"mahabhuta\">elementos</a>. <em>Pauruṣa</em>: «lo propio del varón» (<em>puruṣa</em>); puede entenderse como la hombría o la virilidad, o, en un sentido más amplio, como la capacidad de obrar que hace al ser humano (véase la alternativa).</p>", "interp": [{"titulo": "Lo esencial de cada cosa", "html": "<p>Tras decir que todo está ensartado en él «como perlas en un hilo» (<a class=\"vref\" href=\"capitulo-07.html#v7\" data-v=\"7.7\">7.7</a>), Kṛṣṇa lo muestra cosa por cosa: en cada una es lo que la hace ser lo que es. La lista sigue de cerca la correspondencia clásica entre los elementos y las cualidades que se perciben en ellos: el sabor en el agua, el sonido en el espacio, el olor en la tierra (<a class=\"vref\" href=\"capitulo-07.html#v9\" data-v=\"7.9\">7.9</a>), la luz y el brillo en el sol y en el fuego. Es el primer esbozo de las «manifestaciones» del capítulo 10, donde la serie «yo soy…» se desarrolla por extenso (<a class=\"vref\" href=\"capitulo-10.html#v20\" data-v=\"10.20\">10.20</a>–<a class=\"vref\" href=\"capitulo-10.html#v41\" data-v=\"10.41\">10.41</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Lo que sostiene a cada cosa", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lee el verso como continuación del anterior: el sabor es lo esencial del agua, y por eso las aguas están ensartadas en él, que es ese sabor; del mismo modo lo están las demás cosas en lo que Kṛṣṇa dice ser en ellas. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo explica igual.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Yo soy el sabor en las aguas, oh Kaunteya, la luz de la luna y del sol; soy la sílaba oṃ en todos los Vedas, el sonido en el espacio, la capacidad de obrar en los hombres.", "nota": "<p><em>Pauruṣa</em>, derivado de <em>puruṣa</em>, significa a la vez «hombría, virilidad» y «esfuerzo humano», lo que el hombre consigue con su acción (en la literatura posterior se opone a menudo a <em>daiva</em>, el destino). La traducción principal toma el primer sentido, que es el más inmediato junto a <em>nṛṣu</em>, «en los varones»; la alternativa, el segundo, que no limita la frase a la virilidad y es el de <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, que glosa <em>pauruṣa</em> como «el empeño» (<em>udyama</em>). <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo entienden como «la condición de hombre», aquello por lo que a alguien se le tiene por varón.</p>"}], "ens": "lo-esencial-de-cada-cosa"}, {"n": 9, "hablante": "krsna", "sa": ["पुण्यो गन्धः पृथिव्यां च तेजश्चास्मि विभावसौ ।", "जीवनं सर्वभूतेषु तपश्चास्मि तपस्विषु ॥९॥"], "iast": ["puṇyo gandhaḥ pṛthivyāṃ ca tejaś cāsmi vibhāvasau", "jīvanaṃ sarva-bhūteṣu tapaś cāsmi tapasviṣu"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Soy el aroma puro de la tierra y el <a class=\"t\" href=\"glosario.html#tejas\" data-t=\"tejas\">brillo</a> del fuego; soy la vida en todos los seres y la <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridad</a> en los ascetas.</span>", "palabras": [{"iast": "puṇyaḥ", "sa": "पुण्यः", "gram": "nom. sg. m. adj.", "es": "puro, grato", "analisis": "«meritorio, puro»; dicho de un olor, limpio y agradable"}, {"iast": "gandhaḥ", "sa": "गन्धः", "gram": "nom. sg. m.", "es": "el aroma, el olor"}, {"iast": "pṛthivyām", "sa": "पृथिव्याम्", "gram": "loc. sg. f.", "es": "en la tierra"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "tejaḥ", "sa": "तेजः", "gram": "nom. sg. n.", "es": "el brillo, el ardor", "ref": "tejas", "analisis": "de √tij (ser agudo, afilado)"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres. act.", "es": "soy", "analisis": "√as (ser)"}, {"iast": "vibhāvasau", "sa": "विभावसौ", "gram": "loc. sg. m.", "es": "en el fuego", "ref": "agni", "analisis": "vibhā (resplandor) + vasu (rico): «rico en luz», nombre del fuego"}, {"iast": "jīvanam", "sa": "जीवनम्", "gram": "nom. sg. n.", "es": "la vida, lo que hace vivir", "analisis": "√jīv (vivir)"}, {"iast": "sarva-bhūteṣu", "sa": "सर्वभूतेषु", "gram": "loc. pl. n. comp.", "es": "en todos los seres", "analisis": "sarva (todo) + bhūta (ser, criatura)"}, {"iast": "tapaḥ", "sa": "तपः", "gram": "nom. sg. n.", "es": "la austeridad", "ref": "tapas"}, {"iast": "tapasviṣu", "sa": "तपस्विषु", "gram": "loc. pl. m.", "es": "en los ascetas", "ref": "tapas", "analisis": "tapasvin (el que practica la austeridad)"}], "nota": "<p><em>Puṇya gandha</em>: «olor puro» o «grato»; el olor es la cualidad propia de la tierra, como el sabor lo es del agua. <em>Vibhāvasu</em>: «rico en luz», nombre del fuego. <em>Jīvana</em>: «aquello por lo que se vive», la vida misma de los seres.</p>", "interp": [{"titulo": "Lo mejor de cada cosa", "html": "<p>El adjetivo <em>puṇya</em>, «puro», no es casual: Kṛṣṇa no dice ser cualquier olor, sino el olor limpio de la tierra; no cualquier fuerza, sino la que está libre de deseo (<a class=\"vref\" href=\"capitulo-07.html#v11\" data-v=\"7.11\">7.11</a>). En cada serie se identifica con lo que la cosa tiene de mejor y de más propio, criterio que el capítulo 10 hará explícito al nombrarse lo más alto de cada clase.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-esencial-de-cada-cosa"}, {"n": 10, "hablante": "krsna", "sa": ["बीजं मां सर्वभूतानां विद्धि पार्थ सनातनम् ।", "बुद्धिर्बुद्धिमतामस्मि तेजस्तेजस्विनामहम् ॥१०॥"], "iast": ["bījaṃ māṃ sarva-bhūtānāṃ viddhi pārtha sanātanam", "buddhir buddhimatām asmi tejas tejasvinām aham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Sabe, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, que yo soy la <a class=\"t\" href=\"glosario.html#bija\" data-t=\"bija\">semilla</a> eterna de todos los seres. Soy el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> de los que entienden, el <a class=\"t\" href=\"glosario.html#tejas\" data-t=\"tejas\">esplendor</a> de los espléndidos.</span>", "palabras": [{"iast": "bījam", "sa": "बीजम्", "gram": "ac. sg. n.", "es": "la semilla", "ref": "bija"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "sarva-bhūtānām", "sa": "सर्वभूतानाम्", "gram": "gen. pl. n. comp.", "es": "de todos los seres", "analisis": "sarva (todo) + bhūta (ser)"}, {"iast": "viddhi", "sa": "विद्धि", "gram": "2 sg. impv. act.", "es": "sabe", "analisis": "√vid (saber)"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "sanātanam", "sa": "सनातनम्", "gram": "ac. sg. n. adj.", "es": "eterna", "analisis": "de sanā (siempre): «de siempre, perpetuo»"}, {"iast": "buddhiḥ", "sa": "बुद्धिः", "gram": "nom. sg. f.", "es": "el entendimiento", "ref": "buddhi"}, {"iast": "buddhimatām", "sa": "बुद्धिमताम्", "gram": "gen. pl. m.", "es": "de los que entienden, de los inteligentes", "ref": "buddhi", "analisis": "buddhi + -mat (que posee)"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres. act.", "es": "soy", "analisis": "√as (ser)"}, {"iast": "tejaḥ", "sa": "तेजः", "gram": "nom. sg. n.", "es": "el esplendor", "ref": "tejas"}, {"iast": "tejasvinām", "sa": "तेजस्विनाम्", "gram": "gen. pl. m.", "es": "de los espléndidos, de los que tienen brío", "ref": "tejas", "analisis": "tejas + -vin (que posee)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}], "nota": "<p><em>Sanātana</em>: «de siempre», eterno. Una semilla da un árbol y se agota en él; ésta, en cambio, no se consume al producir los seres. La misma imagen vuelve en <a class=\"vref\" href=\"capitulo-09.html#v18\" data-v=\"9.18\">9.18</a> («la semilla imperecedera») y en <a class=\"vref\" href=\"capitulo-10.html#v39\" data-v=\"10.39\">10.39</a>. <em>Tejas</em>: el brillo del fuego en el verso anterior; aplicado a las personas, el esplendor, el brío o la energía que se impone a los demás.</p>", "interp": [{"titulo": "La semilla y el padre", "html": "<p>La semilla es una de las imágenes con que la Gītā dice que Kṛṣṇa es origen de todo sin dejar de ser él mismo. En el capítulo 14 la completará con otra: la gran naturaleza es el seno donde él deposita el germen, y él es «el padre que da la semilla» (<a class=\"vref\" href=\"capitulo-14.html#v3\" data-v=\"14.3\">14.3</a>–<a class=\"vref\" href=\"capitulo-14.html#v4\" data-v=\"14.4\">14.4</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-esencial-de-cada-cosa"}, {"n": 11, "hablante": "krsna", "sa": ["बलं बलवतां चाहं कामरागविवर्जितम् ।", "धर्माविरुद्धो भूतेषु कामोऽस्मि भरतर्षभ ॥११॥"], "iast": ["balaṃ balavatāṃ cāhaṃ kāma-rāga-vivarjitam", "dharmāviruddho bhūteṣu kāmo 'smi bharatarṣabha"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Soy la fuerza de los fuertes, libre de <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseo</a> y de <a class=\"t\" href=\"glosario.html#raga-dvesa\" data-t=\"raga-dvesa\">apego</a>; y en los seres, oh <a class=\"t\" href=\"glosario.html#bharatarsabha\" data-t=\"bharatarsabha\">Bharatarṣabha</a>, soy el deseo que no se opone al <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a>.</span>", "palabras": [{"iast": "balam", "sa": "बलम्", "gram": "nom. sg. n.", "es": "la fuerza"}, {"iast": "balavatām", "sa": "बलवताम्", "gram": "gen. pl. m.", "es": "de los fuertes", "analisis": "bala + -vat (que posee)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "kāma-rāga-vivarjitam", "sa": "कामरागविवर्जितम्", "gram": "nom. sg. n. comp.", "es": "libre de deseo y de apego", "ref": "kama", "analisis": "kāma (deseo) + rāga (apego, atracción) + vivarjita (privado de), ppp de vi-√vṛj (apartar)"}, {"iast": "dharma-aviruddhaḥ", "sa": "धर्माविरुद्धः", "gram": "nom. sg. m. comp.", "es": "que no se opone al dharma", "ref": "dharma", "analisis": "dharma + aviruddha (no contrario), de a (no) + vi-√rudh (obstruir, oponerse)"}, {"iast": "bhūteṣu", "sa": "भूतेषु", "gram": "loc. pl. n.", "es": "en los seres"}, {"iast": "kāmaḥ", "sa": "कामः", "gram": "nom. sg. m.", "es": "el deseo", "ref": "kama"}, {"iast": "asmi", "sa": "अस्मि", "gram": "1 sg. pres. act.", "es": "soy", "analisis": "√as (ser)"}, {"iast": "bharatarṣabha", "sa": "भरतर्षभ", "gram": "voc. sg. m.", "es": "oh Bharatarṣabha, toro de los Bhāratas", "ref": "bharatarsabha", "analisis": "bharata + ṛṣabha (toro)"}], "nota": "<p><em>Kāma</em> y <em>rāga</em> se distinguen a veces como el deseo de lo que aún no se tiene y el apego a lo que ya se tiene. La fuerza de la que habla Kṛṣṇa es la que no está al servicio de ninguno de los dos: para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, la que basta para sostener el cuerpo; para <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, la que sirve para cumplir el propio deber. <em>Dharmāviruddha</em>: «no contrario al dharma».</p>", "interp": [{"titulo": "El deseo que es Kṛṣṇa", "html": "<p>Hasta aquí la Gītā ha tratado el deseo como el gran enemigo: nace del apego y lleva a la ira (<a class=\"vref\" href=\"capitulo-02.html#v62\" data-v=\"2.62\">2.62</a>), y en <a class=\"vref\" href=\"capitulo-03.html#v37\" data-v=\"3.37\">3.37</a> es «el enemigo en este mundo». Este verso introduce un límite a esa condena: hay un deseo que no se opone al dharma, y ése Kṛṣṇa lo reclama como suyo. La Gītā no pide extinguir todo deseo, sino el que arrastra contra el orden; el otro, ordenado por el dharma, forma parte de la vida que él sostiene.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Deseo y apego", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> distingue los dos términos del compuesto: <em>kāma</em> es el anhelo de los objetos que no se tienen, y <em>rāga</em>, el apego a los que se han obtenido. La fuerza que es Kṛṣṇa, libre de los dos, es la que sirve sólo para sostener el cuerpo y lo demás, no la que en los que transmigran es causa de sed y de apego. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> distinguen los dos términos de modo parecido, pero hacen de esa fuerza la capacidad de cumplir el propio deber.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Soy la fuerza de los fuertes, libre de deseo y de apego; y en los seres, oh Bharatarṣabha, soy el deseo que las escrituras permiten.", "nota": "<p>Si <em>dharma</em> se entiende como la norma que enseñan las escrituras, como lo glosan <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> («el sentido de las escrituras») y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, el deseo «no contrario al dharma» es el que ellas permiten: para Śaṅkara, por ejemplo, el de comer y beber lo necesario para sostener el cuerpo. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> entiende en cambio el propio deber (<em>svadharma</em>). La traducción principal deja <em>dharma</em> sin precisar.</p>"}], "ens": "lo-esencial-de-cada-cosa"}, {"n": 12, "hablante": "krsna", "sa": ["ये चैव सात्त्विका भावा राजसास्तामसाश्च ये ।", "मत्त एवेति तान्विद्धि न त्वहं तेषु ते मयि ॥१२॥"], "iast": ["ye caiva sāttvikā bhāvā rājasās tāmasāś ca ye", "matta eveti tān viddhi na tv ahaṃ teṣu te mayi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y los estados que nacen de <a class=\"t\" href=\"glosario.html#sattva\" data-t=\"sattva\">sattva</a>, de <a class=\"t\" href=\"glosario.html#rajas\" data-t=\"rajas\">rajas</a> y de <a class=\"t\" href=\"glosario.html#tamas\" data-t=\"tamas\">tamas</a>, sabe que proceden sólo de mí; pero yo no estoy en ellos: ellos están en mí.</span>", "palabras": [{"iast": "ye", "sa": "ये", "gram": "nom. pl. m. pron.", "es": "los que"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "también; sólo"}, {"iast": "sāttvikāḥ", "sa": "सात्त्विकाः", "gram": "nom. pl. m.", "es": "de sattva, sāttvicos", "ref": "sattva"}, {"iast": "bhāvāḥ", "sa": "भावाः", "gram": "nom. pl. m.", "es": "los estados, los modos de ser", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "rājasāḥ", "sa": "राजसाः", "gram": "nom. pl. m.", "es": "de rajas, rājasicos", "ref": "rajas"}, {"iast": "tāmasāḥ", "sa": "तामसाः", "gram": "nom. pl. m.", "es": "de tamas, tāmasicos", "ref": "tamas"}, {"iast": "mattaḥ", "sa": "मत्तः", "gram": "abl. sg. pron.", "es": "de mí"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cierra lo que hay que saber)"}, {"iast": "tān", "sa": "तान्", "gram": "ac. pl. m. pron.", "es": "a ellos"}, {"iast": "viddhi", "sa": "विद्धि", "gram": "2 sg. impv. act.", "es": "sabe", "analisis": "√vid (saber)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "teṣu", "sa": "तेषु", "gram": "loc. pl. m. pron.", "es": "en ellos"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "ellos"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg. pron.", "es": "en mí"}], "nota": "<p><em>Bhāva</em>: «estado, modo de ser»; aquí, todo lo que existe en cuanto está hecho de las tres <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>. <em>Matta eva</em>: «sólo de mí». La segunda mitad, «yo no estoy en ellos; ellos están en mí», prepara la paradoja de <a class=\"vref\" href=\"capitulo-09.html#v4\" data-v=\"9.4\">9.4</a>–<a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a>, donde Kṛṣṇa dirá primero que todos los seres están en él y luego que tampoco están en él.</p>", "interp": [{"titulo": "Contener sin ser contenido", "html": "<p>El verso cierra la serie «yo soy…» con una advertencia: que Kṛṣṇa sea el sabor del agua o la fuerza del fuerte no significa que esté encerrado en las cosas o que dependa de ellas. Todo procede de él y descansa en él, pero él no queda atrapado en nada de lo que produce. El verso siguiente da la consecuencia: el mundo, extraviado por esos mismos estados, no lo reconoce (<a class=\"vref\" href=\"capitulo-07.html#v13\" data-v=\"7.13\">7.13</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Y los estados que nacen de sattva, de rajas y de tamas, sabe que proceden sólo de mí; pero yo no dependo de ellos: ellos dependen de mí.", "nota": "<p>Así lo entienden <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>: «estar en» vale aquí por «depender de». Kṛṣṇa no depende de los estados que nacen de las guṇas, como dependen de ellos los seres que transmigran, sino que son ellos los que dependen de él. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> añade que, aunque son su cuerpo, no le sirven de nada, como el cuerpo sirve al alma: son sólo su juego. Lo leen igual <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>; también <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende que su existencia no depende de ellos, y añade que no obtiene de ellos provecho alguno: su único fin es el juego (<em>līlā</em>). La traducción principal conserva la imagen espacial del original.</p>"}], "ens": "yo-no-estoy-en-ellos"}, {"n": 13, "hablante": "krsna", "sa": ["त्रिभिर्गुणमयैर्भावैरेभिः सर्वमिदं जगत् ।", "मोहितं नाभिजानाति मामेभ्यः परमव्ययम् ॥१३॥"], "iast": ["tribhir guṇa-mayair bhāvair ebhiḥ sarvam idaṃ jagat", "mohitaṃ nābhijānāti mām ebhyaḥ param avyayam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Extraviado por estos tres estados hechos de las <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>, el mundo entero no me reconoce a mí, que estoy más allá de ellos y soy imperecedero.</span>", "palabras": [{"iast": "tribhiḥ", "sa": "त्रिभिः", "gram": "instr. pl. m.", "es": "por tres"}, {"iast": "guṇa-mayaiḥ", "sa": "गुणमयैः", "gram": "instr. pl. m. comp.", "es": "hechos de las guṇas", "ref": "guna", "analisis": "guṇa + -maya (hecho de, compuesto de)"}, {"iast": "bhāvaiḥ", "sa": "भावैः", "gram": "instr. pl. m.", "es": "estados", "analisis": "√bhū (ser): «estado, modo de ser»"}, {"iast": "ebhiḥ", "sa": "एभिः", "gram": "instr. pl. m. pron.", "es": "estos"}, {"iast": "sarvam", "sa": "सर्वम्", "gram": "nom. sg. n.", "es": "entero, todo"}, {"iast": "idam", "sa": "इदम्", "gram": "nom. sg. n. pron.", "es": "este"}, {"iast": "jagat", "sa": "जगत्", "gram": "nom. sg. n.", "es": "mundo", "analisis": "de √gam (ir): «lo que se mueve»"}, {"iast": "mohitam", "sa": "मोहितम्", "gram": "nom. sg. n. ppp", "es": "extraviado", "ref": "moha", "analisis": "caus. de √muh (extraviarse)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "abhijānāti", "sa": "अभिजानाति", "gram": "3 sg. pres. act.", "es": "reconoce", "analisis": "abhi-√jñā (reconocer)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "me, a mí"}, {"iast": "ebhyaḥ", "sa": "एभ्यः", "gram": "abl. pl. m. pron.", "es": "de ellos"}, {"iast": "param", "sa": "परम्", "gram": "ac. sg. m. adj.", "es": "más allá, por encima"}, {"iast": "avyayam", "sa": "अव्ययम्", "gram": "ac. sg. m. adj.", "es": "imperecedero", "analisis": "a (no) + vyaya (merma, pérdida)"}], "nota": "<p><em>Bhāva</em>: «estado, modo de ser»; son los estados <em>sāttvika</em>, <em>rājasa</em> y <em>tāmasa</em> del verso anterior (<a class=\"vref\" href=\"capitulo-07.html#v12\" data-v=\"7.12\">7.12</a>). <em>Param</em>: «más allá, por encima» de ellos. <em>Avyaya</em>: «imperecedero, que no mengua».</p>", "interp": [{"titulo": "Por encima de las guṇas", "html": "<p>El verso cierra la enumeración anterior: Kṛṣṇa está en todo como su esencia (<a class=\"vref\" href=\"capitulo-07.html#v8\" data-v=\"7.8\">7.8</a>–<a class=\"vref\" href=\"capitulo-07.html#v12\" data-v=\"7.12\">7.12</a>), pero los estados que producen las guṇas atraen la mirada y ocultan al que los sostiene; el mundo ve los efectos y no reconoce su origen. La idea de estar «más allá de las guṇas» volverá en <a class=\"vref\" href=\"capitulo-14.html#v19\" data-v=\"14.19\">14.19</a>–<a class=\"vref\" href=\"capitulo-14.html#v26\" data-v=\"14.26\">14.26</a>, aplicada al sabio que las trasciende.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "cruzar-la-maya"}, {"n": 14, "hablante": "krsna", "sa": ["दैवी ह्येषा गुणमयी मम माया दुरत्यया ।", "मामेव ये प्रपद्यन्ते मायामेतां तरन्ति ते ॥१४॥"], "iast": ["daivī hy eṣā guṇa-mayī mama māyā duratyayā", "mām eva ye prapadyante māyām etāṃ taranti te"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Porque esta <a class=\"t\" href=\"glosario.html#maya\" data-t=\"maya\">māyā</a> mía, divina, hecha de las <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>, es difícil de cruzar; los que se <a class=\"t\" href=\"glosario.html#prapatti\" data-t=\"prapatti\">refugian</a> sólo en mí cruzan esta māyā.</span>", "palabras": [{"iast": "daivī", "sa": "दैवी", "gram": "nom. sg. f. adj.", "es": "divina", "ref": "deva", "analisis": "derivado de deva (dios): «propio de un dios, divino»"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque, en verdad"}, {"iast": "eṣā", "sa": "एषा", "gram": "nom. sg. f. pron.", "es": "esta"}, {"iast": "guṇa-mayī", "sa": "गुणमयी", "gram": "nom. sg. f. comp.", "es": "hecha de las guṇas", "ref": "guna", "analisis": "guṇa + -maya (hecho de)"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "mía"}, {"iast": "māyā", "sa": "माया", "gram": "nom. sg. f.", "es": "māyā", "ref": "maya"}, {"iast": "duratyayā", "sa": "दुरत्यया", "gram": "nom. sg. f. adj.", "es": "difícil de cruzar", "analisis": "dus (difícil) + atyaya (paso más allá; ati-√i)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "sólo"}, {"iast": "ye", "sa": "ये", "gram": "nom. pl. m. rel.", "es": "los que"}, {"iast": "prapadyante", "sa": "प्रपद्यन्ते", "gram": "3 pl. pres. med.", "es": "se refugian", "ref": "prapatti", "analisis": "pra-√pad (acudir en busca de amparo)"}, {"iast": "māyām", "sa": "मायाम्", "gram": "ac. sg. f.", "es": "la māyā", "ref": "maya"}, {"iast": "etām", "sa": "एताम्", "gram": "ac. sg. f. pron.", "es": "esta"}, {"iast": "taranti", "sa": "तरन्ति", "gram": "3 pl. pres. act.", "es": "cruzan", "analisis": "√tṝ (atravesar, cruzar un río)"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "ellos"}], "nota": "<p><em>Daivī</em>: «divina», propia del dios. <em>Duratyaya</em>: «difícil de pasar más allá». <em>Taranti</em>, «cruzan», es el verbo con que se atraviesa un río: la māyā es como una corriente que no se cruza por las propias fuerzas. <em>Prapadyante</em>: «acuden en busca de amparo», de <em>pra</em>-√<em>pad</em> (véase <a class=\"t\" href=\"glosario.html#prapatti\" data-t=\"prapatti\">prapatti</a>); es el verbo que Arjuna usó para sí mismo en <a class=\"vref\" href=\"capitulo-02.html#v7\" data-v=\"2.7\">2.7</a>.</p>", "interp": [{"titulo": "El poder que engaña", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende la māyā como el poder del Señor, hecho de las tres guṇas, que le pertenece como su propia naturaleza y engaña a todos los seres. La cruzan quienes se refugian en él, el poseedor de esa māyā, como en su propio sí-mismo, y quedan libres de la atadura del mundo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La naturaleza real que vela al Señor", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, la māyā de este verso es la naturaleza material, hecha de las guṇas: real, no ilusoria. Se llama «divina» porque es obra del Señor, que crea como por juego, y es ella la que oculta su naturaleza propia a los seres. Además de ocultarlo, hace que los seres tengan por gozosos los objetos. Quien se refugia en él la atraviesa: la deja atrás y lo adora sólo a él.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Porque este poder de ilusión, divino y mío, hecho de las guṇas, es difícil de cruzar; los que se refugian sólo en mí atraviesan esta ilusión.", "nota": "<p>Hace explícito el sentido de <em>māyā</em> como «ilusión», el de la lectura del <a class=\"t\" href=\"glosario.html#advaita\" data-t=\"advaita\">Advaita</a>: <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> la llama aquí «la que engaña a todos los seres» y a Kṛṣṇa «el poseedor de la māyā» (<em>māyāvin</em>), y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> la identifica con la ignorancia (<em>avidyā</em>) que oculta lo real y hace aparecer el mundo. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende en cambio aquí la māyā como la naturaleza material (<em>prakṛti</em>) hecha de las guṇas, real, a la que se da ese nombre porque produce efectos maravillosos. Por eso la traducción principal deja la palabra sin traducir (véase la ficha <a class=\"t\" href=\"glosario.html#maya\" data-t=\"maya\">māyā</a>).</p>"}], "ens": "cruzar-la-maya"}, {"n": 15, "hablante": "krsna", "sa": ["न मां दुष्कृतिनो मूढाः प्रपद्यन्ते नराधमाः ।", "माययापहृतज्ञाना आसुरं भावमाश्रिताः ॥१५॥"], "iast": ["na māṃ duṣkṛtino mūḍhāḥ prapadyante narādhamāḥ", "māyayāpahṛta-jñānā āsuraṃ bhāvam āśritāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">No se refugian en mí los malhechores, los necios, los más viles de los hombres, aquellos a quienes la <a class=\"t\" href=\"glosario.html#maya\" data-t=\"maya\">māyā</a> ha arrebatado el conocimiento y que se han acogido a la condición <a class=\"t\" href=\"glosario.html#asura\" data-t=\"asura\">demoníaca</a>.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "en mí"}, {"iast": "duṣkṛtinaḥ", "sa": "दुष्कृतिनः", "gram": "nom. pl. m.", "es": "los malhechores", "analisis": "dus (mal) + kṛta (hecho) + -in"}, {"iast": "mūḍhāḥ", "sa": "मूढाः", "gram": "nom. pl. m. ppp", "es": "los necios", "ref": "moha", "analisis": "√muh (extraviarse)"}, {"iast": "prapadyante", "sa": "प्रपद्यन्ते", "gram": "3 pl. pres. med.", "es": "se refugian", "ref": "prapatti", "analisis": "pra-√pad"}, {"iast": "nara-adhamāḥ", "sa": "नराधमाः", "gram": "nom. pl. m. comp.", "es": "los más viles de los hombres", "analisis": "nara (hombre) + adhama (el más bajo)"}, {"iast": "māyayā", "sa": "मायया", "gram": "instr. sg. f.", "es": "por la māyā", "ref": "maya"}, {"iast": "apahṛta-jñānāḥ", "sa": "अपहृतज्ञानाः", "gram": "nom. pl. m. comp.", "es": "privados de conocimiento", "ref": "jnana", "analisis": "apahṛta (arrebatado; apa-√hṛ) + jñāna (conocimiento)"}, {"iast": "āsuram", "sa": "आसुरम्", "gram": "ac. sg. m. adj.", "es": "demoníaca", "ref": "asura", "analisis": "derivado de asura"}, {"iast": "bhāvam", "sa": "भावम्", "gram": "ac. sg. m.", "es": "condición", "analisis": "√bhū (ser): «estado, condición»"}, {"iast": "āśritāḥ", "sa": "आश्रिताः", "gram": "nom. pl. m. ppp", "es": "acogidos a", "analisis": "ā-√śri (apoyarse en, acogerse a)"}], "nota": "<p><em>Duṣkṛtin</em>: «el que obra mal», opuesto a los <em>sukṛtin</em>, «los que obran bien», del verso siguiente. <em>Narādhama</em>: «el más bajo de los hombres». <em>Āsuraṃ bhāvam</em>: «la condición de los <a class=\"t\" href=\"glosario.html#asura\" data-t=\"asura\">asuras</a>»; el capítulo 16 describirá por extenso esa naturaleza demoníaca (<a class=\"vref\" href=\"capitulo-16.html#v4\" data-v=\"16.4\">16.4</a>–<a class=\"vref\" href=\"capitulo-16.html#v20\" data-v=\"16.20\">16.20</a>).</p>", "interp": [{"titulo": "Cuatro grados de alejamiento", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee los calificativos como cuatro clases de malhechores, cada una peor que la anterior: los necios, que se equivocan sobre sí mismos y sobre el Señor; los más viles, que lo conocen de un modo general pero no son capaces de volverse a él; aquellos a quienes argumentos engañosos han arrebatado el conocimiento que ya tenían de él y de su señorío; y los de condición demoníaca, cuyo conocimiento firme de él sólo les sirve para odiarlo. En esta lectura forman el reverso de las cuatro clases de virtuosos del verso siguiente, que él ordena también según el grado de sus buenas obras. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> y <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> leen en cambio los calificativos como eslabones de una cadena de causas, no como clases distintas.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "cruzar-la-maya"}, {"n": 16, "hablante": "krsna", "sa": ["चतुर्विधा भजन्ते मां जनाः सुकृतिनोऽर्जुन ।", "आर्तो जिज्ञासुरर्थार्थी ज्ञानी च भरतर्षभ ॥१६॥"], "iast": ["catur-vidhā bhajante māṃ janāḥ sukṛtino 'rjuna", "ārto jijñāsur arthārthī jñānī ca bharatarṣabha"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Cuatro clases de personas virtuosas me <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">adoran</a>, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>: el afligido, el que desea conocer, el que busca riqueza y el <a class=\"t\" href=\"glosario.html#jnanin\" data-t=\"jnanin\">sabio</a>, oh <a class=\"t\" href=\"glosario.html#bharatarsabha\" data-t=\"bharatarsabha\">Bharatarṣabha</a>.</span>", "palabras": [{"iast": "catur-vidhāḥ", "sa": "चतुर्विधाः", "gram": "nom. pl. m. comp.", "es": "de cuatro clases", "analisis": "catur (cuatro) + vidha (clase)"}, {"iast": "bhajante", "sa": "भजन्ते", "gram": "3 pl. pres. med.", "es": "adoran", "ref": "bhakti", "analisis": "√bhaj (participar, adherirse, adorar)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "me, a mí"}, {"iast": "janāḥ", "sa": "जनाः", "gram": "nom. pl. m.", "es": "personas"}, {"iast": "sukṛtinaḥ", "sa": "सुकृतिनः", "gram": "nom. pl. m.", "es": "virtuosas", "analisis": "su (bien) + kṛta (hecho) + -in: «que obran bien»"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}, {"iast": "ārtaḥ", "sa": "आर्तः", "gram": "nom. sg. m. ppp", "es": "el afligido", "analisis": "ā-√ṛ: «caído en desgracia, afligido»"}, {"iast": "jijñāsuḥ", "sa": "जिज्ञासुः", "gram": "nom. sg. m.", "es": "el que desea conocer", "analisis": "desiderativo de √jñā (conocer)"}, {"iast": "artha-arthī", "sa": "अर्थार्थी", "gram": "nom. sg. m. comp.", "es": "el que busca riqueza", "analisis": "artha (riqueza, bienes, fin) + arthin (el que busca)"}, {"iast": "jñānī", "sa": "ज्ञानी", "gram": "nom. sg. m.", "es": "el sabio", "ref": "jnanin", "analisis": "jñāna (conocimiento) + -in"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "bharata-ṛṣabha", "sa": "भरतर्षभ", "gram": "voc. sg. m. comp.", "es": "oh Bharatarṣabha", "ref": "bharatarsabha"}], "nota": "<p><em>Sukṛtin</em>: «el que obra bien», «el virtuoso». <em>Ārta</em>: «afligido, el que está en apuros». <em>Jijñāsu</em>: desiderativo de √<em>jñā</em>, «el que desea conocer». <em>Arthārthin</em>: «el que busca <em>artha</em>»: riqueza, bienes, poder. <em>Jñānin</em>: «el que conoce» (véase la ficha <a class=\"t\" href=\"glosario.html#jnanin\" data-t=\"jnanin\">jñānin</a>).</p>", "interp": [{"titulo": "También el que pide", "html": "<p>Lo notable del verso es que los cuatro son llamados virtuosos, también el que acude a Kṛṣṇa por necesidad o por interés. Los versos siguientes ordenan esas motivaciones y ponen al sabio por encima (<a class=\"vref\" href=\"capitulo-07.html#v17\" data-v=\"7.17\">7.17</a>–<a class=\"vref\" href=\"capitulo-07.html#v18\" data-v=\"7.18\">7.18</a>), pero no excluyen a ninguno: todos son «nobles».</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Las cuatro clases según Śaṅkara", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica que el afligido es el que sufre el ataque de un ladrón, de una fiera o de una enfermedad; el que desea conocer quiere conocer la verdad del Señor; el que busca riqueza desea bienes; y el sabio es el que conoce la verdad de Viṣṇu.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Lo que cada uno busca", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> distingue a los cuatro por lo que desean: el afligido ha perdido su prosperidad y quiere recobrarla; el que busca riqueza desea la que aún no tiene, y los dos, dice, forman en el fondo una sola clase, porque ambos buscan prosperidad; el que desea conocer quiere alcanzar el propio sí-mismo separado de la naturaleza; y el sabio, que sabe que su ser consiste en pertenecer al Señor, no se detiene en el sí-mismo aislado y quiere al Señor mismo.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "las-cuatro-clases-de-devotos"}, {"n": 17, "hablante": "krsna", "sa": ["तेषां ज्ञानी नित्ययुक्त एकभक्तिर्विशिष्यते ।", "प्रियो हि ज्ञानिनोऽत्यर्थमहं स च मम प्रियः ॥१७॥"], "iast": ["teṣāṃ jñānī nitya-yukta eka-bhaktir viśiṣyate", "priyo hi jñānino 'tyartham ahaṃ sa ca mama priyaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">De ellos sobresale el <a class=\"t\" href=\"glosario.html#jnanin\" data-t=\"jnanin\">sabio</a>, siempre <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido en yoga</a> y de <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoción</a> única; porque yo le soy sobremanera querido al sabio, y él me es querido a mí.</span>", "palabras": [{"iast": "teṣām", "sa": "तेषाम्", "gram": "gen. pl. m. pron.", "es": "de ellos"}, {"iast": "jñānī", "sa": "ज्ञानी", "gram": "nom. sg. m.", "es": "el sabio", "ref": "jnanin"}, {"iast": "nitya-yuktaḥ", "sa": "नित्ययुक्तः", "gram": "nom. sg. m. comp.", "es": "siempre unido", "ref": "yukta", "analisis": "nitya (siempre) + yukta (unido en yoga)"}, {"iast": "eka-bhaktiḥ", "sa": "एकभक्तिः", "gram": "nom. sg. m. comp.", "es": "de devoción única", "ref": "bhakti", "analisis": "eka (uno, único) + bhakti (devoción)"}, {"iast": "viśiṣyate", "sa": "विशिष्यते", "gram": "3 sg. pres. pas.", "es": "sobresale", "analisis": "vi-√śiṣ (distinguirse)"}, {"iast": "priyaḥ", "sa": "प्रियः", "gram": "nom. sg. m. adj.", "es": "querido"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque"}, {"iast": "jñāninaḥ", "sa": "ज्ञानिनः", "gram": "gen. sg. m.", "es": "para el sabio", "ref": "jnanin"}, {"iast": "atyartham", "sa": "अत्यर्थम्", "gram": "ind.", "es": "sobremanera", "analisis": "ati (más allá) + artha (medida)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "él"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "para mí"}, {"iast": "priyaḥ", "sa": "प्रियः", "gram": "nom. sg. m. adj.", "es": "querido"}], "nota": "<p><em>Nitya-yukta</em>: «siempre unido (en yoga)». <em>Eka-bhakti</em>: «de devoción a uno solo», que no se dirige a nada más. <em>Atyartham</em>: «sobremanera, más allá de toda medida». El amor es recíproco: el verso lo dice dos veces, de él a Kṛṣṇa y de Kṛṣṇa a él.</p>", "interp": [{"titulo": "Lo más querido es el propio sí-mismo", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica por qué el Señor es tan querido para el sabio: el Señor es el propio sí-mismo del sabio, y, como todos saben, el propio sí-mismo es lo querido; y el sabio, a su vez, es el propio sí-mismo del Señor, y por eso le es sobremanera querido. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> da la misma razón.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Un amor que no cabe en palabras", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> comenta <em>atyartham</em> diciendo que ni el propio Señor puede expresar cuánto le es querido al sabio; y él, a su vez, le es querido del mismo modo.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "las-cuatro-clases-de-devotos"}, {"n": 18, "hablante": "krsna", "sa": ["उदाराः सर्व एवैते ज्ञानी त्वात्मैव मे मतम् ।", "आस्थितः स हि युक्तात्मा मामेवानुत्तमां गतिम् ॥१८॥"], "iast": ["udārāḥ sarva evaite jñānī tv ātmaiva me matam", "āsthitaḥ sa hi yuktātmā mām evānuttamāṃ gatim"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Todos ellos son nobles, pero al <a class=\"t\" href=\"glosario.html#jnanin\" data-t=\"jnanin\">sabio</a> lo tengo por mi propio ser; porque él, con el ser <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido en yoga</a>, se ha asentado sólo en mí, la meta insuperable.</span>", "palabras": [{"iast": "udārāḥ", "sa": "उदाराः", "gram": "nom. pl. m. adj.", "es": "nobles", "analisis": "«elevado, generoso, noble»"}, {"iast": "sarve", "sa": "सर्वे", "gram": "nom. pl. m.", "es": "todos"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "en verdad"}, {"iast": "ete", "sa": "एते", "gram": "nom. pl. m. pron.", "es": "ellos"}, {"iast": "jñānī", "sa": "ज्ञानी", "gram": "nom. sg. m.", "es": "el sabio", "ref": "jnanin"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "ātmā", "sa": "आत्मा", "gram": "nom. sg. m.", "es": "propio ser", "ref": "atman"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "mismo"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mi"}, {"iast": "matam", "sa": "मतम्", "gram": "nom. sg. n. ppp", "es": "así lo considero", "analisis": "√man (pensar, considerar)"}, {"iast": "āsthitaḥ", "sa": "आस्थितः", "gram": "nom. sg. m. ppp", "es": "asentado", "analisis": "ā-√sthā (establecerse en)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "él"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque"}, {"iast": "yukta-ātmā", "sa": "युक्तात्मा", "gram": "nom. sg. m. comp.", "es": "con el ser unido en yoga", "ref": "yukta", "analisis": "yukta (unido) + ātman (ser, sí-mismo)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "en mí"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "sólo"}, {"iast": "anuttamām", "sa": "अनुत्तमाम्", "gram": "ac. sg. f. adj.", "es": "insuperable", "analisis": "an (no) + uttama (supremo): «sin otro superior»"}, {"iast": "gatim", "sa": "गतिम्", "gram": "ac. sg. f.", "es": "meta", "analisis": "√gam (ir): «camino, meta»"}], "nota": "<p><em>Udāra</em>: «elevado, generoso, noble». <em>Ātmaiva me matam</em>: «es mi propio ser: así lo considero». <em>Anuttamā gatiḥ</em>: «la meta sobre la que no hay otra».</p>", "interp": [{"titulo": "No distinto de mí", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, como para <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, el sabio no es otro que el Señor: «es mi propio sí-mismo». Los otros tres también son nobles, porque ningún devoto suyo le es ingrato; pero el sabio le es sobremanera querido, porque se ha unido a él con la convicción «yo soy Vāsudeva y no otro». La misma identidad la afirma <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Sin él no podría vivir", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee <em>ātmā</em> como «aquello de lo que depende mi vida»: así como el sabio no puede vivir sin el Señor, el Señor no se sostiene sin el sabio. Es una de las expresiones más audaces del amor recíproco entre Dios y el devoto.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Todos ellos son nobles, pero el sabio es como mi propia vida: sin él no podría sostenerme; porque él, con el ser unido en yoga, se ha asentado sólo en mí, la meta insuperable.", "nota": "<p>Sigue la lectura de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>: <em>ātmā</em> no indica aquí identidad, sino que el Señor hace depender de su devoto su propio sostén, como el devoto no puede vivir sin él. Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, en cambio, el sabio es el propio sí-mismo del Señor en sentido literal: no es distinto de él. La traducción principal deja abierta la frase.</p>"}], "ens": "las-cuatro-clases-de-devotos"}, {"n": 19, "hablante": "krsna", "sa": ["बहूनां जन्मनामन्ते ज्ञानवान्मां प्रपद्यते ।", "वासुदेवः सर्वमिति स महात्मा सुदुर्लभः ॥१९॥"], "iast": ["bahūnāṃ janmanām ante jñānavān māṃ prapadyate", "vāsudevaḥ sarvam iti sa mahātmā sudurlabhaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Al cabo de muchos nacimientos, el que tiene <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> se <a class=\"t\" href=\"glosario.html#prapatti\" data-t=\"prapatti\">refugia</a> en mí: «<a class=\"t\" href=\"glosario.html#krsna\" data-t=\"krsna\">Vāsudeva</a> es todo». Un <a class=\"t\" href=\"glosario.html#mahatman\" data-t=\"mahatman\">gran ser</a> así es muy difícil de encontrar.</span>", "palabras": [{"iast": "bahūnām", "sa": "बहूनाम्", "gram": "gen. pl. n.", "es": "de muchos"}, {"iast": "janmanām", "sa": "जन्मनाम्", "gram": "gen. pl. n.", "es": "nacimientos", "analisis": "janman (nacimiento; √jan)"}, {"iast": "ante", "sa": "अन्ते", "gram": "loc. sg. m.", "es": "al final"}, {"iast": "jñānavān", "sa": "ज्ञानवान्", "gram": "nom. sg. m. adj.", "es": "el que tiene conocimiento", "ref": "jnana", "analisis": "jñāna + -vat (dotado de)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "en mí"}, {"iast": "prapadyate", "sa": "प्रपद्यते", "gram": "3 sg. pres. med.", "es": "se refugia", "ref": "prapatti", "analisis": "pra-√pad"}, {"iast": "vāsudevaḥ", "sa": "वासुदेवः", "gram": "nom. sg. m.", "es": "Vāsudeva", "ref": "krsna", "analisis": "patronímico: «hijo de Vasudeva»"}, {"iast": "sarvam", "sa": "सर्वम्", "gram": "nom. sg. n.", "es": "todo"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cierra la cita)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ese"}, {"iast": "mahā-ātmā", "sa": "महात्मा", "gram": "nom. sg. m. comp.", "es": "gran ser", "ref": "mahatman", "analisis": "mahat (grande) + ātman (sí-mismo)"}, {"iast": "su-durlabhaḥ", "sa": "सुदुर्लभः", "gram": "nom. sg. m. adj.", "es": "muy difícil de encontrar", "analisis": "su (muy) + dur-labha (difícil de obtener; √labh)"}], "nota": "<p><em>Bahūnāṃ janmanām ante</em>: «al final de muchos nacimientos»; recuerda al yogui que se perfecciona «a lo largo de muchos nacimientos» (<a class=\"vref\" href=\"capitulo-06.html#v45\" data-v=\"6.45\">6.45</a>). <em>Vāsudeva</em>: patronímico de Kṛṣṇa, «hijo de <a class=\"t\" href=\"glosario.html#vasudeva\" data-t=\"vasudeva\">Vasudeva</a>». <em>Iti</em> cierra la cita: es la convicción con que el sabio se refugia. <em>Mahātman</em>: «de gran sí-mismo», «gran ser».</p>", "interp": [{"titulo": "Todo es Vāsudeva", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, el que llega al final de muchos nacimientos tiene un conocimiento ya maduro y alcanza directamente a Vāsudeva, el sí-mismo interior, sabiendo que «Vāsudeva es todo»; quien así lo reconoce como el sí-mismo de todo es un gran ser sin igual ni superior, y por eso muy raro. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> leen también la fórmula como la visión de todo en Vāsudeva, pero entienden <em>prapadyate</em> como «me adora».</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Vāsudeva, todo para mí", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende la fórmula como la convicción del sabio de que Vāsudeva es para él todo: lo que hay que alcanzar, el medio para alcanzarlo y cuanto puede desear.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "La causa de todas las causas", "html": "<p>Prabhupāda vierte <em>vāsudevaḥ sarvam</em> como «la causa de todas las causas y todo lo que es»; en su comentario lo explica como ver cada cosa en relación con Vāsudeva, de quien el mundo material no es independiente, y concluye que «todo es Vāsudeva».</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Al cabo de muchos nacimientos, el que tiene conocimiento se refugia en mí, sabiendo que todo es Vāsudeva. Un gran ser así es muy difícil de encontrar.", "nota": "<p>Lee la fórmula como identidad: todo cuanto existe es Vāsudeva, el sí-mismo de todo. Así <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, y en el mismo sentido <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>.</p>"}, {"html": "Al cabo de muchos nacimientos, el que tiene conocimiento se refugia en mí, pensando: «Vāsudeva lo es todo para mí». Un gran ser así es muy difícil de encontrar.", "nota": "<p>Con <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>: Vāsudeva es para el sabio su meta, el medio para alcanzarla y todo cuanto desea.</p>"}], "ens": "las-cuatro-clases-de-devotos"}, {"n": 20, "hablante": "krsna", "sa": ["कामैस्तैस्तैर्हृतज्ञानाः प्रपद्यन्तेऽन्यदेवताः ।", "तं तं नियममास्थाय प्रकृत्या नियताः स्वया ॥२०॥"], "iast": ["kāmais tais tair hṛta-jñānāḥ prapadyante 'nya-devatāḥ", "taṃ taṃ niyamam āsthāya prakṛtyā niyatāḥ svayā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Aquellos a quienes estos o aquellos <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseos</a> les han arrebatado el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> acuden a otras <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">divinidades</a>, siguiendo esta o aquella norma, llevados por su propia <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a>.</span>", "palabras": [{"iast": "kāmaiḥ", "sa": "कामैः", "gram": "ins. pl. m.", "es": "por los deseos", "ref": "kama"}, {"iast": "taiḥ", "sa": "तैः", "gram": "ins. pl. m.", "es": "por estos", "analisis": "tad, repetido: valor distributivo, «este o aquel»"}, {"iast": "taiḥ", "sa": "तैः", "gram": "ins. pl. m.", "es": "o aquellos"}, {"iast": "hṛta-jñānāḥ", "sa": "हृतज्ञानाः", "gram": "nom. pl. m. comp. (bahuvrīhi)", "es": "aquellos a quienes se ha arrebatado el conocimiento", "ref": "jnana", "analisis": "hṛta (arrebatado, de √hṛ «llevarse») + jñāna (conocimiento)"}, {"iast": "prapadyante", "sa": "प्रपद्यन्ते", "gram": "3 pl. pres. med.", "es": "acuden a, se refugian en", "ref": "prapatti", "analisis": "pra + √pad (ir hacia; acogerse a)"}, {"iast": "anya-devatāḥ", "sa": "अन्यदेवताः", "gram": "ac. pl. f. comp.", "es": "a otras divinidades", "ref": "deva", "analisis": "anya (otro) + devatā (divinidad)"}, {"iast": "tam tam", "sa": "तं तम्", "gram": "ac. sg. m. (repetido)", "es": "esta o aquella"}, {"iast": "niyamam", "sa": "नियमम्", "gram": "ac. sg. m.", "es": "norma, observancia", "analisis": "ni + √yam (sujetar, regular)"}, {"iast": "āsthāya", "sa": "आस्थाय", "gram": "abs.", "es": "siguiendo, ateniéndose a", "analisis": "ā + √sthā (estar, establecerse)"}, {"iast": "prakṛtyā", "sa": "प्रकृत्या", "gram": "ins. sg. f.", "es": "por su naturaleza", "ref": "prakrti"}, {"iast": "niyatāḥ", "sa": "नियताः", "gram": "nom. pl. m. part.", "es": "llevados, determinados", "analisis": "ni + √yam"}, {"iast": "svayā", "sa": "स्वया", "gram": "ins. sg. f.", "es": "propia"}], "nota": "<p><em>Prapadyante</em>, «acuden», «se acogen a», es el verbo con que el capítulo habla de refugiarse en Kṛṣṇa (<a class=\"vref\" href=\"capitulo-07.html#v14\" data-v=\"7.14\">7.14</a>, <a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a>): aquí el refugio se busca en otra parte. <em>Niyama</em> son las observancias propias del culto de cada divinidad: ayunos, ofrendas, días y fórmulas. <em>Prakṛti</em> tiene el sentido de la naturaleza propia de cada uno, sus inclinaciones, como en <a class=\"vref\" href=\"capitulo-03.html#v33\" data-v=\"3.33\">3.33</a>: el verso no condena, describe por qué cada cual busca lo que busca.</p>", "interp": [{"titulo": "Deseos que nublan", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> concreta los deseos: hijos, ganado, el cielo. Las «otras divinidades» son las distintas de Vāsudeva, el sí-mismo, y la «naturaleza propia» que los lleva es la impronta que traen de vidas anteriores, como entienden también <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>; para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, en cambio, es la inclinación al mal (<em>pāpa-vāsanā</em>) que los ata a lo hecho de guṇas.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Ya en el capítulo 4", "html": "<p>El verso retoma lo que Kṛṣṇa había dicho en <a class=\"vref\" href=\"capitulo-04.html#v12\" data-v=\"4.12\">4.12</a>: quienes desean el éxito de sus acciones sacrifican aquí a los dioses, porque en el mundo humano el éxito que nace de la acción llega pronto. Los versos siguientes añaden lo nuevo: también esa fe la sostiene Kṛṣṇa.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-fe-en-otros-dioses"}, {"n": 21, "hablante": "krsna", "sa": ["यो यो यां यां तनुं भक्तः श्रद्धयार्चितुमिच्छति ।", "तस्य तस्याचलां श्रद्धां तामेव विदधाम्यहम् ॥२१॥"], "iast": ["yo yo yāṃ yāṃ tanuṃ bhaktaḥ śraddhayārcitum icchati", "tasya tasyācalāṃ śraddhāṃ tām eva vidadhāmy aham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Cualquiera que sea la forma divina que un <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoto</a> quiera adorar con <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a>, yo hago inquebrantable en él esa misma fe.</span>", "palabras": [{"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien", "analisis": "repetido: valor distributivo, «cada cual que»"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "(cada cual)"}, {"iast": "yām", "sa": "याम्", "gram": "ac. sg. f. rel.", "es": "cualquier", "analisis": "repetido: «cualquiera que sea»"}, {"iast": "yām", "sa": "याम्", "gram": "ac. sg. f. rel.", "es": "(que sea)"}, {"iast": "tanum", "sa": "तनुम्", "gram": "ac. sg. f.", "es": "forma, cuerpo", "analisis": "tanu (cuerpo, figura)"}, {"iast": "bhaktaḥ", "sa": "भक्तः", "gram": "nom. sg. m. part.", "es": "devoto", "ref": "bhakti", "analisis": "part. de √bhaj (participar, servir, adorar)"}, {"iast": "śraddhayā", "sa": "श्रद्धया", "gram": "ins. sg. f.", "es": "con fe", "ref": "sraddha"}, {"iast": "arcitum", "sa": "अर्चितुम्", "gram": "inf.", "es": "adorar, rendir culto", "analisis": "√arc (honrar, venerar)"}, {"iast": "icchati", "sa": "इच्छति", "gram": "3 sg. pres. act.", "es": "desea", "analisis": "√iṣ (desear)"}, {"iast": "tasya tasya", "sa": "तस्य तस्य", "gram": "gen. sg. m. (repetido)", "es": "de cada uno de ellos"}, {"iast": "acalām", "sa": "अचलाम्", "gram": "ac. sg. f.", "es": "inquebrantable", "analisis": "a (no) + cala (que se mueve, de √cal)"}, {"iast": "śraddhām", "sa": "श्रद्धाम्", "gram": "ac. sg. f.", "es": "fe", "ref": "sraddha"}, {"iast": "tām", "sa": "ताम्", "gram": "ac. sg. f.", "es": "esa"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "misma"}, {"iast": "vidadhāmi", "sa": "विदधामि", "gram": "1 sg. pres. act.", "es": "establezco, hago firme", "analisis": "vi + √dhā (poner, disponer)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}], "nota": "<p><em>Tanu</em> es «cuerpo» o «forma»; aquí, la forma divina a la que se rinde culto. <em>Arc</em> es el verbo del culto con ofrendas y flores (de él viene <em>arcā</em>, la imagen que se venera). Lo notable del verso es que Kṛṣṇa no corrige la fe ajena: la afianza, sea cual sea su objeto. Es la misma disposición de <a class=\"vref\" href=\"capitulo-04.html#v11\" data-v=\"4.11\">4.11</a>: «como se acercan a mí, así los acojo».</p>", "interp": [{"titulo": "Una fe sostenida desde arriba", "html": "<p>La Gītā no exige que el devoto de otra divinidad cambie de objeto para que su fe sea sostenida: la fe misma, sea cual sea su destino, la afianza Kṛṣṇa. El límite no está en la fe, sino en lo que se le pide; de eso tratan los dos versos siguientes.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Cualquiera que sea el cuerpo mío, la divinidad, que un devoto quiera adorar con fe, yo hago inquebrantable en él esa misma fe.", "nota": "<p>Tomando <em>tanu</em>, «cuerpo», como cuerpo del propio Kṛṣṇa: las divinidades son su cuerpo y él es su sí-mismo, de modo que quien las adora lo adora a él sin saberlo. Es la lectura de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, coherente con su idea del mundo como cuerpo del Señor; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> llama también a esa forma «mi propia figura», y él y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> dicen en <a class=\"vref\" href=\"capitulo-07.html#v23\" data-v=\"7.23\">7.23</a> que todas las divinidades son formas de Kṛṣṇa y que su culto es, en realidad, culto a él. <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, en cambio, entiende las formas de Brahmā y de los demás dioses, no las de Kṛṣṇa. Prepara lo que dirá <a class=\"vref\" href=\"capitulo-09.html#v23\" data-v=\"9.23\">9.23</a>.</p>"}], "ens": "la-fe-en-otros-dioses"}, {"n": 22, "hablante": "krsna", "sa": ["स तया श्रद्धया युक्तस्तस्याराधनमीहते ।", "लभते च ततः कामान्मयैव विहितान्हि तान् ॥२२॥"], "iast": ["sa tayā śraddhayā yuktas tasyārādhanam īhate", "labhate ca tataḥ kāmān mayaiva vihitān hi tān"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Unido a esa <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a>, se empeña en el culto de esa divinidad, y de ella obtiene lo que <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">desea</a>; pero, en verdad, soy yo quien se lo concede.</span>", "palabras": [{"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m.", "es": "él"}, {"iast": "tayā", "sa": "तया", "gram": "ins. sg. f.", "es": "con esa"}, {"iast": "śraddhayā", "sa": "श्रद्धया", "gram": "ins. sg. f.", "es": "fe", "ref": "sraddha"}, {"iast": "yuktaḥ", "sa": "युक्तः", "gram": "nom. sg. m. part.", "es": "unido a, provisto de", "analisis": "√yuj (uncir, unir)"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg.", "es": "de él (del dios al que rinde culto)"}, {"iast": "ārādhanam", "sa": "आराधनम्", "gram": "ac. sg. n.", "es": "el culto, la propiciación", "analisis": "ā + √rādh (propiciar, complacer)"}, {"iast": "īhate", "sa": "ईहते", "gram": "3 sg. pres. med.", "es": "procura, se empeña en", "analisis": "√īh (esforzarse por)"}, {"iast": "labhate", "sa": "लभते", "gram": "3 sg. pres. med.", "es": "obtiene", "analisis": "√labh (obtener)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "tataḥ", "sa": "ततः", "gram": "ind.", "es": "de ella, de ahí"}, {"iast": "kāmān", "sa": "कामान्", "gram": "ac. pl. m.", "es": "lo que desea, sus deseos", "ref": "kama"}, {"iast": "mayā", "sa": "मया", "gram": "ins. sg.", "es": "por mí"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "vihitān", "sa": "विहितान्", "gram": "ac. pl. m. part.", "es": "dispuestos, concedidos", "analisis": "vi + √dhā (disponer)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "en verdad"}, {"iast": "tān", "sa": "तान्", "gram": "ac. pl. m.", "es": "esos"}], "nota": "<p><em>Ārādhana</em> es el culto que busca propiciar, ganarse el favor de la divinidad. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> dividen <em>tasyā rādhanam</em>, «el culto de ella» (de la forma divina, <em>tanu</em>, que es femenino), y glosan <em>rādhanam</em> por <em>ārādhanam</em>: el sentido es el mismo. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> divide <em>tasya ārādhanam</em>, «el culto de él» (de Indra u otro dios). La segunda mitad pone las cosas en su orden: el fruto llega por medio de la divinidad (<em>tataḥ</em>, «de ella»), pero quien lo dispone es Kṛṣṇa. Lo dirá con más fuerza en <a class=\"vref\" href=\"capitulo-09.html#v24\" data-v=\"9.24\">9.24</a>: él es quien disfruta de todos los sacrificios y su señor.</p>", "interp": [{"titulo": "El que reparte los frutos", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica que los frutos llegan dispuestos por el Señor supremo, que, por ser omnisciente, conoce cómo corresponde cada fruto a cada acción. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> dice lo mismo, y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> añaden que esas divinidades son formas suyas. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo explica igual; él y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> añaden que el Señor da el fruto como gobernante interior (<em>antaryāmin</em>) de cada divinidad, y Śrīdhara, que las divinidades dependen de él y son formas suyas.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-fe-en-otros-dioses"}, {"n": 23, "hablante": "krsna", "sa": ["अन्तवत्तु फलं तेषां तद्भवत्यल्पमेधसाम् ।", "देवान्देवयजो यान्ति मद्भक्ता यान्ति मामपि ॥२३॥"], "iast": ["antavat tu phalaṃ teṣāṃ tad bhavaty alpa-medhasām", "devān deva-yajo yānti mad-bhaktā yānti mām api"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero el <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a> de esos hombres de poco entendimiento tiene fin: los que sacrifican a los <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">dioses</a> van a los dioses; mis <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devotos</a>, en cambio, vienen a mí.</span>", "palabras": [{"iast": "antavat", "sa": "अन्तवत्", "gram": "nom. sg. n.", "es": "perecedero, que tiene fin", "analisis": "anta (fin) + -vat (que posee)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "phalam", "sa": "फलम्", "gram": "nom. sg. n.", "es": "el fruto", "ref": "phala"}, {"iast": "teṣām", "sa": "तेषाम्", "gram": "gen. pl. m.", "es": "de ellos"}, {"iast": "tat", "sa": "तत्", "gram": "nom. sg. n.", "es": "ese"}, {"iast": "bhavati", "sa": "भवति", "gram": "3 sg. pres. act.", "es": "es", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "alpa-medhasām", "sa": "अल्पमेधसाम्", "gram": "gen. pl. m. comp. (bahuvrīhi)", "es": "de los de poco entendimiento", "analisis": "alpa (poco) + medhas (inteligencia, sabiduría)"}, {"iast": "devān", "sa": "देवान्", "gram": "ac. pl. m.", "es": "a los dioses", "ref": "deva"}, {"iast": "deva-yajaḥ", "sa": "देवयजः", "gram": "nom. pl. m. comp.", "es": "los que sacrifican a los dioses", "ref": "yajna", "analisis": "deva (dios) + yaj (que sacrifica, de √yaj)"}, {"iast": "yānti", "sa": "यान्ति", "gram": "3 pl. pres. act.", "es": "van", "analisis": "√yā (ir)"}, {"iast": "mad-bhaktāḥ", "sa": "मद्भक्ताः", "gram": "nom. pl. m. comp.", "es": "mis devotos", "ref": "bhakti", "analisis": "mad (yo, en composición) + bhakta (devoto)"}, {"iast": "yānti", "sa": "यान्ति", "gram": "3 pl. pres. act.", "es": "van"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "en cambio, también"}], "nota": "<p><em>Antavat</em>, «que tiene fin»: el fruto que dan los dioses es real, pero se agota, como se agota el cielo que se gana con los ritos (<a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>). La segunda mitad tiene la forma de una regla: cada cual llega a aquello que adora. <a class=\"vref\" href=\"capitulo-09.html#v25\" data-v=\"9.25\">9.25</a> la desarrollará con dos casos más: los que se consagran a los antepasados van a los antepasados, y a los espíritus, los que sacrifican a los espíritus.</p>", "interp": [{"titulo": "El mismo esfuerzo", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lee en el verso la compasión (<em>anukrośa</em>) del propio Señor: aunque el esfuerzo sea el mismo, los hombres no se refugian en él para obtener un fruto sin fin, y se conforman con frutos que se acaban: «¡ay, qué penosa es su situación!». La idea del mismo esfuerzo aparece también en <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y en <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Adorar es llegar", "html": "<p>La Gītā no niega que los dioses den lo que se les pide; establece una correspondencia entre lo que se adora y aquello a lo que se llega. El mismo principio aparece en la hora de la muerte: uno va a aquello en que piensa al morir (<a class=\"vref\" href=\"capitulo-08.html#v6\" data-v=\"8.6\">8.6</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-fe-en-otros-dioses"}, {"n": 24, "hablante": "krsna", "sa": ["अव्यक्तं व्यक्तिमापन्नं मन्यन्ते मामबुद्धयः ।", "परं भावमजानन्तो ममाव्ययमनुत्तमम् ॥२४॥"], "iast": ["avyaktaṃ vyaktim āpannaṃ manyante mām abuddhayaḥ", "paraṃ bhāvam ajānanto mamāvyayam anuttamam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los faltos de <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> creen que yo, que no era <a class=\"t\" href=\"glosario.html#avyakta\" data-t=\"avyakta\">manifiesto</a>, he venido a manifestarme, porque no conocen mi estado supremo, imperecedero, insuperable.</span>", "palabras": [{"iast": "avyaktam", "sa": "अव्यक्तम्", "gram": "ac. sg. m.", "es": "no manifiesto", "ref": "avyakta", "analisis": "a (no) + vyakta (manifiesto, de vi-√añj)"}, {"iast": "vyaktim", "sa": "व्यक्तिम्", "gram": "ac. sg. f.", "es": "la manifestación", "analisis": "vi + √añj (manifestar)"}, {"iast": "āpannam", "sa": "आपन्नम्", "gram": "ac. sg. m. part.", "es": "llegado a", "analisis": "ā + √pad (llegar a, caer en)"}, {"iast": "manyante", "sa": "मन्यन्ते", "gram": "3 pl. pres. med.", "es": "creen, piensan", "analisis": "√man (pensar)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "abuddhayaḥ", "sa": "अबुद्धयः", "gram": "nom. pl. m. comp. (bahuvrīhi)", "es": "los faltos de entendimiento", "ref": "buddhi", "analisis": "a (sin) + buddhi (entendimiento)"}, {"iast": "param", "sa": "परम्", "gram": "ac. sg. m.", "es": "supremo"}, {"iast": "bhāvam", "sa": "भावम्", "gram": "ac. sg. m.", "es": "estado, naturaleza", "analisis": "√bhū (ser)"}, {"iast": "ajānantaḥ", "sa": "अजानन्तः", "gram": "nom. pl. m. part. pres.", "es": "sin conocer", "analisis": "a (no) + √jñā (conocer)"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg.", "es": "mi"}, {"iast": "avyayam", "sa": "अव्ययम्", "gram": "ac. sg. m.", "es": "imperecedero", "analisis": "a (no) + vyaya (pérdida, gasto)"}, {"iast": "anuttamam", "sa": "अनुत्तमम्", "gram": "ac. sg. m.", "es": "insuperable", "analisis": "an (no) + uttama (el más alto): «que no tiene otro más alto»"}], "nota": "<p><em>Avyaktaṃ vyaktim āpannam</em>, literalmente «no manifiesto, llegado a la manifestación». La traducción principal lo entiende como el juicio de quien ve en Kṛṣṇa a un ser que antes no existía y ahora ha nacido, como cualquier otro, sin advertir que su nacimiento es libre y que su naturaleza no empieza ni acaba (<a class=\"vref\" href=\"capitulo-04.html#v6\" data-v=\"4.6\">4.6</a>–<a class=\"vref\" href=\"capitulo-04.html#v9\" data-v=\"4.9\">4.9</a>); así <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>. La frase admite otras lecturas. Para <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, <em>avyakta</em> es el que no tiene un cuerpo producido, y el error de los necios es creer que lo ha tomado; Viśvanātha Cakravartī, de la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, lo entiende como el brahman sin forma, y el error, como creer que ha nacido en casa de Vasudeva con una forma ilusoria. La discusión entre escuelas ha sido larga (véase la alternativa y la ficha <a class=\"t\" href=\"glosario.html#avyakta\" data-t=\"avyakta\">avyakta</a>). <em>Anuttama</em>, «sin otro más alto», es el superlativo negado: lo que no tiene por encima nada superior.</p>", "interp": [{"titulo": "Antes oculto, ahora visible", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo entiende así: los que carecen de discernimiento creen que el Señor, antes no manifiesto, invisible, se ha hecho ahora visible, aunque es el Señor eterno y siempre establecido; no conocen su naturaleza suprema, la del sí-mismo supremo, imperecedera e insuperable. Que lo toman por un ser más, nacido como los demás, lo dicen expresamente <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Un nacimiento que no viene del karma", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee la frase como <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> —antes no manifiesto, ahora manifiesto—, pero precisa en qué está el error: los «faltos de entendimiento» toman a Kṛṣṇa por un príncipe cualquiera, que se ha manifestado al obtener un nacimiento determinado por el peso de sus acciones. No saben que el Señor de todo, sin dejar su naturaleza, ha descendido como hijo de Vasudeva por compasión y por amor a los que se acogen a él, para ser refugio de todos; que nace por su propia voluntad lo había explicado a propósito de <a class=\"vref\" href=\"capitulo-04.html#v6\" data-v=\"4.6\">4.6</a>.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Los faltos de entendimiento creen que yo soy lo no manifiesto, sin forma, que ha tomado una forma manifiesta, porque no conocen mi estado supremo, imperecedero, insuperable.", "nota": "<p>La tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a> lee así el verso. Prabhupāda traduce que los poco inteligentes creen que Kṛṣṇa «era impersonal antes y ahora ha asumido esta personalidad»: el error está en tener su forma personal por algo secundario, sobrepuesto a un absoluto sin forma; y, según su comentario, de ahí nace también el de tomarlo por un hombre más, «sólo el hijo de Devakī y Vasudeva».</p>"}], "ens": "el-senor-velado"}, {"n": 25, "hablante": "krsna", "sa": ["नाहं प्रकाशः सर्वस्य योगमायासमावृतः ।", "मूढोऽयं नाभिजानाति लोको मामजमव्ययम् ॥२५॥"], "iast": ["nāhaṃ prakāśaḥ sarvasya yoga-māyā-samāvṛtaḥ", "mūḍho 'yaṃ nābhijānāti loko mām ajam avyayam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">No me muestro a todos, velado como estoy por mi <a class=\"t\" href=\"glosario.html#yoga-maya\" data-t=\"yoga-maya\">yoga-māyā</a>; este mundo <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extraviado</a> no me reconoce a mí, el no nacido, el imperecedero.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "prakāśaḥ", "sa": "प्रकाशः", "gram": "nom. sg. m.", "es": "manifiesto, visible", "analisis": "pra + √kāś (brillar, aparecer)"}, {"iast": "sarvasya", "sa": "सर्वस्य", "gram": "gen. sg.", "es": "para todos"}, {"iast": "yoga-māyā-samāvṛtaḥ", "sa": "योगमायासमावृतः", "gram": "nom. sg. m. comp.", "es": "velado por la yoga-māyā", "ref": "yoga-maya", "analisis": "yoga (poder, unión) + māyā (poder prodigioso) + samāvṛta (cubierto, de sam-ā-√vṛ «cubrir»)"}, {"iast": "mūḍhaḥ", "sa": "मूढः", "gram": "nom. sg. m. part.", "es": "extraviado", "ref": "moha", "analisis": "part. de √muh (extraviarse)"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m.", "es": "este"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "abhijānāti", "sa": "अभिजानाति", "gram": "3 sg. pres. act.", "es": "reconoce", "analisis": "abhi + √jñā (conocer, reconocer)"}, {"iast": "lokaḥ", "sa": "लोकः", "gram": "nom. sg. m.", "es": "el mundo, la gente"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "ajam", "sa": "अजम्", "gram": "ac. sg. m.", "es": "no nacido", "analisis": "a (no) + ja (nacido, de √jan)"}, {"iast": "avyayam", "sa": "अव्ययम्", "gram": "ac. sg. m.", "es": "imperecedero"}], "nota": "<p><em>Prakāśa</em> es «luz» y «lo que está a la vista»: Kṛṣṇa no es visible para todos. La causa es la <em>yoga-māyā</em>, un compuesto que la Gītā sólo usa aquí y que cada escuela entiende a su modo (véase la ficha <a class=\"t\" href=\"glosario.html#yoga-maya\" data-t=\"yoga-maya\">yoga-māyā</a>). Enlaza con la māyā por la que Kṛṣṇa nace (<a class=\"vref\" href=\"capitulo-04.html#v6\" data-v=\"4.6\">4.6</a>) y con la que extravía a los que no se refugian en él (<a class=\"vref\" href=\"capitulo-07.html#v14\" data-v=\"7.14\">7.14</a>–<a class=\"vref\" href=\"capitulo-07.html#v15\" data-v=\"7.15\">7.15</a>). <em>Aja</em>, «no nacido», y <em>avyaya</em>, «imperecedero», responden a lo que el verso anterior decía de los necios: lo creen nacido y no conocen lo que en él no perece.</p>", "interp": [{"titulo": "El velo de las guṇas", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> glosa <em>yoga</em> como la unión de las <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a> y llama <em>yoga-māyā</em> a la māyā que consiste en esa unión: cubierto por ella, el Señor no se revela a todos, sino sólo a algunos de sus devotos. Esa yoga-māyā, por ser suya, no le impide a él conocer, como la magia no engaña al mago. Que sólo se muestra a sus devotos lo dicen también <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>; la glosa de <em>yoga</em> por las guṇas es sólo de Śaṅkara.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Una energía que vela y revela", "html": "<p>La tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a> distingue la <em>yoga-māyā</em>, energía interna de Kṛṣṇa, de la <em>mahā-māyā</em>, la que extravía a los seres en el mundo. La yoga-māyā oculta a Kṛṣṇa a quienes no tienen devoción, y es la misma que, ante sus devotos, dispone sus juegos y su presencia. Por eso el verso no habla de un engaño, sino de una reserva: Kṛṣṇa sólo se deja conocer por la devoción (<a class=\"vref\" href=\"capitulo-11.html#v54\" data-v=\"11.54\">11.54</a>).</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "No me muestro a todos, envuelto en la māyā que nace de la unión de las guṇas; este mundo extraviado no me reconoce a mí, el no nacido, el imperecedero.", "nota": "<p>Con <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, que entiende <em>yoga</em> como la unión o combinación de las tres <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>: la <em>yoga-māyā</em> sería la māyā hecha de esa unión, la misma que <a class=\"vref\" href=\"capitulo-07.html#v14\" data-v=\"7.14\">7.14</a> llama «hecha de las guṇas». Otras lecturas entienden <em>yoga</em> de otro modo: <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, «por mi poder (<em>yoga</em>) y por la māyā»; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, como un despliegue inconcebible de su sabiduría, y la māyā como su habilidad para hacer posible lo imposible; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, como su voluntad (<em>saṅkalpa</em>), a la que obedece la māyā; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, como la forma humana, y las demás, que asume. Las dos primeras se acercan al «yoga soberano» de <a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a>; la traducción principal deja el compuesto sin traducir.</p>"}], "ens": "el-senor-velado"}, {"n": 26, "hablante": "krsna", "sa": ["वेदाहं समतीतानि वर्तमानानि चार्जुन ।", "भविष्याणि च भूतानि मां तु वेद न कश्चन ॥२६॥"], "iast": ["vedāhaṃ samatītāni vartamānāni cārjuna", "bhaviṣyāṇi ca bhūtāni māṃ tu veda na kaścana"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Conozco, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>, a los seres que fueron, a los que son y a los que serán; pero a mí nadie me conoce.</span>", "palabras": [{"iast": "veda", "sa": "वेद", "gram": "1 sg. perf. (con valor de presente)", "es": "conozco", "analisis": "√vid (saber, conocer)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "samatītāni", "sa": "समतीतानि", "gram": "ac. pl. n. part.", "es": "los pasados", "analisis": "sam + ati + √i (pasar más allá)"}, {"iast": "vartamānāni", "sa": "वर्तमानानि", "gram": "ac. pl. n. part. pres. med.", "es": "los presentes", "analisis": "√vṛt (estar, existir)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}, {"iast": "bhaviṣyāṇi", "sa": "भविष्याणि", "gram": "ac. pl. n.", "es": "los venideros", "analisis": "√bhū (ser), futuro"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "bhūtāni", "sa": "भूतानि", "gram": "ac. pl. n.", "es": "los seres", "analisis": "√bhū (llegar a ser)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "veda", "sa": "वेद", "gram": "3 sg. perf. (con valor de presente)", "es": "conoce", "analisis": "√vid"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "kaścana", "sa": "कश्चन", "gram": "nom. sg. m.", "es": "nadie (con na)", "analisis": "kaḥ (quién) + cana (partícula indefinida)"}], "nota": "<p><em>Veda</em> es un perfecto con valor de presente, «sé, conozco», de la misma raíz que <em>Veda</em>. En sánscrito la forma es igual para la primera y la tercera persona: el verso empieza con <em>vedāham</em>, «yo conozco», y termina con <em>veda na kaścana</em>, «nadie conoce», con la misma palabra; el español no puede conservar el eco. El capítulo había empezado diciendo que, entre miles, apenas uno lo conoce de verdad (<a class=\"vref\" href=\"capitulo-07.html#v3\" data-v=\"7.3\">7.3</a>).</p>", "interp": [{"titulo": "Nadie, salvo el que se refugia", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> matiza el «nadie»: nadie lo conoce, salvo el devoto que se ha refugiado en él; y es la falta de ese conocimiento la que hace que los hombres no lo adoren. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo explica del mismo modo. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> dice lo mismo casi con las mismas palabras.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Lo que sólo él conoce", "html": "<p>El tema volverá en el capítulo 10: ni los dioses ni los grandes sabios conocen su origen (<a class=\"vref\" href=\"capitulo-10.html#v2\" data-v=\"10.2\">10.2</a>), y Arjuna dirá que sólo Kṛṣṇa se conoce a sí mismo por sí mismo (<a class=\"vref\" href=\"capitulo-10.html#v15\" data-v=\"10.15\">10.15</a>). La Gītā no lo presenta como un misterio cerrado: lo que no se alcanza conociendo como se conoce un objeto se alcanza por la devoción (<a class=\"vref\" href=\"capitulo-11.html#v54\" data-v=\"11.54\">11.54</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-senor-velado"}, {"n": 27, "hablante": "krsna", "sa": ["इच्छाद्वेषसमुत्थेन द्वन्द्वमोहेन भारत ।", "सर्वभूतानि सम्मोहं सर्गे यान्ति परन्तप ॥२७॥"], "iast": ["icchā-dveṣa-samutthena dvandva-mohena bhārata", "sarva-bhūtāni sammohaṃ sarge yānti parantapa"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Por el <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extravío</a> de los pares de opuestos, nacido del deseo y de la aversión, oh <a class=\"t\" href=\"glosario.html#bharata\" data-t=\"bharata\">Bhārata</a>, todos los seres caen en la confusión al nacer, oh <a class=\"t\" href=\"glosario.html#parantapa\" data-t=\"parantapa\">Parantapa</a>.</span>", "palabras": [{"iast": "icchā-dveṣa-samutthena", "sa": "इच्छाद्वेषसमुत्थेन", "gram": "instr. sg. m. comp.", "es": "nacido del deseo y de la aversión", "ref": "raga-dvesa", "analisis": "icchā (deseo) + dveṣa (aversión) + samuttha (surgido; sam-ut-√sthā)"}, {"iast": "dvandva-mohena", "sa": "द्वन्द्वमोहेन", "gram": "instr. sg. m. comp.", "es": "por el extravío de los pares de opuestos", "ref": "moha", "analisis": "dvandva (par, pareja de opuestos) + moha (extravío)"}, {"iast": "bhārata", "sa": "भारत", "gram": "voc. sg. m.", "es": "oh Bhārata", "ref": "bharata"}, {"iast": "sarva-bhūtāni", "sa": "सर्वभूतानि", "gram": "nom. pl. n. comp.", "es": "todos los seres", "analisis": "sarva (todo) + bhūta (ser, lo que ha llegado a ser)"}, {"iast": "sammoham", "sa": "सम्मोहम्", "gram": "ac. sg. m.", "es": "en la confusión", "ref": "moha", "analisis": "sam (del todo) + moha (extravío)"}, {"iast": "sarge", "sa": "सर्गे", "gram": "loc. sg. m.", "es": "al nacer", "analisis": "sarga (emisión, creación, nacimiento; √sṛj, «emitir»)"}, {"iast": "yānti", "sa": "यान्ति", "gram": "3 pl. pres.", "es": "caen, van", "analisis": "√yā (ir)"}, {"iast": "parantapa", "sa": "परन्तप", "gram": "voc. sg. m.", "es": "oh Parantapa", "ref": "parantapa"}], "nota": "<p><em>Dvandva</em>: «par»; los pares de opuestos, como el frío y el calor o el placer y el dolor, de los que el sabio está libre (<a class=\"vref\" href=\"capitulo-02.html#v45\" data-v=\"2.45\">2.45</a>, <a class=\"vref\" href=\"capitulo-05.html#v3\" data-v=\"5.3\">5.3</a>). <em>Dvandva-moha</em> es el extravío que producen: tomar por real la oposición entre lo grato y lo ingrato y vivir pendiente de ella. <em>Icchā</em> y <em>dveṣa</em>, deseo y aversión, son la pareja que <a class=\"vref\" href=\"capitulo-03.html#v34\" data-v=\"3.34\">3.34</a> llama <a class=\"t\" href=\"glosario.html#raga-dvesa\" data-t=\"raga-dvesa\">atracción y aversión</a>. <em>Sammoha</em>: «confusión completa». <em>Sarge</em>: véase la alternativa.</p>", "interp": [{"titulo": "Por qué el mundo no lo conoce", "html": "<p>El capítulo ha dado ya dos razones de que el mundo no conozca a Kṛṣṇa: las tres <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>, que lo tienen extraviado (<a class=\"vref\" href=\"capitulo-07.html#v13\" data-v=\"7.13\">7.13</a>), y la <a class=\"t\" href=\"glosario.html#maya\" data-t=\"maya\">māyā</a> con que él mismo se cubre (<a class=\"vref\" href=\"capitulo-07.html#v25\" data-v=\"7.25\">7.25</a>). Este verso da la tercera, vista desde los seres: el deseo y la aversión engendran la confusión de los opuestos, y en ella se nace. No se presenta como una culpa, sino como la condición de partida de todos; el verso siguiente dice quiénes salen de ella.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Por el extravío de los pares de opuestos, nacido del deseo y de la aversión, oh Bhārata, todos los seres caen en la confusión desde la creación, oh Parantapa.", "nota": "<p><em>Sarge</em> es el locativo de <em>sarga</em>, «emisión, creación» (de √<em>sṛj</em>, «emitir»). Puede entenderse del nacimiento de cada ser, como en la traducción principal y en la glosa de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> («en el nacimiento, en el momento de nacer»), que comparten <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, o de la creación del mundo: desde que el mundo es emitido, los seres viven en el extravío.</p>"}], "ens": "el-extravio-de-los-opuestos"}, {"n": 28, "hablante": "krsna", "sa": ["येषां त्वन्तगतं पापं जनानां पुण्यकर्मणाम् ।", "ते द्वन्द्वमोहनिर्मुक्ता भजन्ते मां दृढव्रताः ॥२८॥"], "iast": ["yeṣāṃ tv anta-gataṃ pāpaṃ janānāṃ puṇya-karmaṇām", "te dvandva-moha-nirmuktā bhajante māṃ dṛḍha-vratāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero los hombres de obras meritorias en quienes el <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a> ha llegado a su fin, libres del <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extravío</a> de los pares de opuestos, me <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">adoran</a> firmes en su voto.</span>", "palabras": [{"iast": "yeṣām", "sa": "येषाम्", "gram": "gen. pl. m. rel.", "es": "de quienes, en quienes"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "anta-gatam", "sa": "अन्तगतम्", "gram": "nom. sg. n. comp.", "es": "llegado a su fin", "analisis": "anta (fin) + gata (ido; √gam)"}, {"iast": "pāpam", "sa": "पापम्", "gram": "nom. sg. n.", "es": "el pecado", "ref": "papa"}, {"iast": "janānām", "sa": "जनानाम्", "gram": "gen. pl. m.", "es": "de los hombres, de las personas"}, {"iast": "puṇya-karmaṇām", "sa": "पुण्यकर्मणाम्", "gram": "gen. pl. m. comp.", "es": "de obras meritorias", "ref": "karma", "analisis": "puṇya (meritorio, puro) + karman (acción, obra)"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "ésos"}, {"iast": "dvandva-moha-nirmuktāḥ", "sa": "द्वन्द्वमोहनिर्मुक्ताः", "gram": "nom. pl. m. comp.", "es": "libres del extravío de los opuestos", "ref": "moha", "analisis": "dvandva (par de opuestos) + moha (extravío) + nirmukta (liberado; nir-√muc)"}, {"iast": "bhajante", "sa": "भजन्ते", "gram": "3 pl. pres. med.", "es": "adoran", "ref": "bhakti", "analisis": "√bhaj (participar, adorar, servir)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "me, a mí"}, {"iast": "dṛḍha-vratāḥ", "sa": "दृढव्रताः", "gram": "nom. pl. m. comp.", "es": "firmes en su voto", "analisis": "dṛḍha (firme) + vrata (voto, observancia)"}], "nota": "<p><em>Anta-gata</em>: «llegado a su fin», agotado. <em>Puṇya-karman</em>: «de obras meritorias»; <em>puṇya</em>, el mérito, es lo opuesto a <em>pāpa</em> (véase la ficha <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a>). <em>Dṛḍha-vrata</em>: «de voto firme»; <em>vrata</em> es el voto o la observancia que uno se impone, y aquí la firmeza con que se mantiene la devoción.</p>", "interp": [{"titulo": "Del extravío a la devoción", "html": "<p>El verso recoge el hilo de <a class=\"vref\" href=\"capitulo-07.html#v16\" data-v=\"7.16\">7.16</a>, donde los que adoran a Kṛṣṇa son «personas virtuosas», literalmente «de buenas obras» (<em>janāḥ sukṛtinaḥ</em>); aquí son «hombres de obras meritorias» (<em>janānāṃ puṇya-karmaṇām</em>). La devoción no sustituye a la acción recta: viene después de ella, cuando las buenas obras han agotado el pecado, igual que en <a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a> el sabio llega a Kṛṣṇa «al cabo de muchos nacimientos».</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-extravio-de-los-opuestos"}, {"n": 29, "hablante": "krsna", "sa": ["जरामरणमोक्षाय मामाश्रित्य यतन्ति ये ।", "ते ब्रह्म तद्विदुः कृत्स्नमध्यात्मं कर्म चाखिलम् ॥२९॥"], "iast": ["jarā-maraṇa-mokṣāya mām āśritya yatanti ye", "te brahma tad viduḥ kṛtsnam adhyātmaṃ karma cākhilam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los que, refugiados en mí, se esfuerzan por liberarse de la vejez y de la muerte conocen ese <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, todo <a class=\"t\" href=\"glosario.html#adhyatma\" data-t=\"adhyatma\">lo relativo al sí-mismo</a> y la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a> entera.</span>", "palabras": [{"iast": "jarā-maraṇa-mokṣāya", "sa": "जरामरणमोक्षाय", "gram": "dat. sg. m. comp.", "es": "para liberarse de la vejez y de la muerte", "ref": "moksa", "analisis": "jarā (vejez) + maraṇa (muerte; √mṛ) + mokṣa (liberación)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "en mí"}, {"iast": "āśritya", "sa": "आश्रित्य", "gram": "abs.", "es": "refugiándose en", "analisis": "ā-√śri (apoyarse en, acogerse a)"}, {"iast": "yatanti", "sa": "यतन्ति", "gram": "3 pl. pres.", "es": "se esfuerzan", "analisis": "√yat (esforzarse)"}, {"iast": "ye", "sa": "ये", "gram": "nom. pl. m. rel.", "es": "los que"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "ésos"}, {"iast": "brahma", "sa": "ब्रह्म", "gram": "ac. sg. n.", "es": "brahman", "ref": "brahman"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "ese"}, {"iast": "viduḥ", "sa": "विदुः", "gram": "3 pl. perf. (valor de presente)", "es": "conocen", "analisis": "√vid (saber)"}, {"iast": "kṛtsnam", "sa": "कृत्स्नम्", "gram": "ac. sg. n. adj.", "es": "entero, todo"}, {"iast": "adhyātmam", "sa": "अध्यात्मम्", "gram": "ac. sg. n.", "es": "lo relativo al sí-mismo", "ref": "adhyatma", "analisis": "adhi (sobre, respecto de) + ātman (sí-mismo)"}, {"iast": "karma", "sa": "कर्म", "gram": "ac. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "akhilam", "sa": "अखिलम्", "gram": "ac. sg. n. adj.", "es": "entera, sin resto", "analisis": "a (no) + khila (resto, hueco)"}], "nota": "<p><em>Jarā-maraṇa</em>: «vejez y muerte», el sufrimiento que trae consigo todo cuerpo. <em>Āśritya</em>: «apoyándose en, acogiéndose a»; la palabra de la que viene <em>āśraya</em>, «refugio». <em>Adhyātma</em>: «lo relativo al sí-mismo» (véase la ficha <a class=\"t\" href=\"glosario.html#adhyatma\" data-t=\"adhyatma\">adhyātma</a>). Ni este término ni la «acción» se explican aquí: <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a> preguntará por ellos al comienzo del capítulo siguiente (<a class=\"vref\" href=\"capitulo-08.html#v1\" data-v=\"8.1\">8.1</a>).</p>", "interp": [{"titulo": "Conocer brahman entero", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, como para <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, «ese brahman» es el brahman supremo, y quienes se acogen al Señor supremo, con la mente puesta en él, para librarse de la vejez y de la muerte llegan a conocerlo, junto con todo lo que concierne al sí-mismo interior (<em>pratyag-ātman</em>) y la acción entera. También <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> entienden aquí el brahman supremo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Tres clases de aspirantes", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> ve en estos dos versos a dos aspirantes distintos del sabio de <a class=\"vref\" href=\"capitulo-07.html#v17\" data-v=\"7.17\">7.17</a>. En este verso, el que busca librarse de la vejez y de la muerte, es decir, la visión del propio sí-mismo, libre de la naturaleza material; para él, el «brahman» de este verso es ese sí-mismo en su pureza. En <a class=\"vref\" href=\"capitulo-07.html#v30\" data-v=\"7.30\">7.30</a>, por la repetición de «los que», el que busca la prosperidad, que reúne al afligido y al que busca riqueza de <a class=\"vref\" href=\"capitulo-07.html#v16\" data-v=\"7.16\">7.16</a>: a él le toca conocer a Kṛṣṇa junto con lo relativo a los seres y a los dioses, mientras que lo relativo al sacrificio vale para los tres, también para el sabio. Son las tres clases de aspirantes —la prosperidad, el sí-mismo, el Señor—, ya distinguidas por Yāmuna, y el capítulo 8 dirá qué debe conocer y practicar cada una y cómo lo conoce en la hora de la muerte.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Los que, refugiados en mí, se esfuerzan por liberarse de la vejez y de la muerte conocen ese brahman en su totalidad, lo relativo al sí-mismo y la acción entera.", "nota": "<p><em>Kṛtsnam</em>, «entero», es neutro singular, como <em>brahma</em> y como <em>adhyātmam</em>: puede ir con el uno o con el otro. La traducción principal lo une a <em>adhyātmam</em>, que lo sigue inmediatamente, como hacen <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>; la alternativa, a brahman: lo que se conoce «entero» es brahman mismo.</p>"}], "ens": "conocerlo-por-entero"}, {"n": 30, "hablante": "krsna", "sa": ["साधिभूताधिदैवं मां साधियज्ञं च ये विदुः ।", "प्रयाणकालेऽपि च मां ते विदुर्युक्तचेतसः ॥३०॥"], "iast": ["sādhibhūtādhidaivaṃ māṃ sādhiyajñaṃ ca ye viduḥ", "prayāṇa-kāle 'pi ca māṃ te vidur yukta-cetasaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y los que me conocen junto con <a class=\"t\" href=\"glosario.html#adhibhuta\" data-t=\"adhibhuta\">lo relativo a los seres</a>, <a class=\"t\" href=\"glosario.html#adhidaiva\" data-t=\"adhidaiva\">lo relativo a los dioses</a> y <a class=\"t\" href=\"glosario.html#adhiyajna\" data-t=\"adhiyajna\">lo relativo al sacrificio</a>, ésos, con la mente <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unida en yoga</a>, me conocen también en la hora de la muerte.</span>", "palabras": [{"iast": "sādhibhūtādhidaivam", "sa": "साधिभूताधिदैवम्", "gram": "ac. sg. m. comp.", "es": "junto con lo relativo a los seres y a los dioses", "ref": "adhibhuta", "analisis": "sa (con) + adhibhūta (lo relativo a los seres) + adhidaiva (lo relativo a los dioses)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "me, a mí"}, {"iast": "sādhiyajñam", "sa": "साधियज्ञम्", "gram": "ac. sg. m. comp.", "es": "junto con lo relativo al sacrificio", "ref": "adhiyajna", "analisis": "sa (con) + adhiyajña (lo relativo al sacrificio)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "ye", "sa": "ये", "gram": "nom. pl. m. rel.", "es": "los que"}, {"iast": "viduḥ", "sa": "विदुः", "gram": "3 pl. perf. (valor de presente)", "es": "conocen", "analisis": "√vid (saber)"}, {"iast": "prayāṇa-kāle", "sa": "प्रयाणकाले", "gram": "loc. sg. m. comp.", "es": "en la hora de la partida", "analisis": "prayāṇa (partida, salida; pra-√yā) + kāla (tiempo, hora)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también, aun"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "ésos"}, {"iast": "yukta-cetasaḥ", "sa": "युक्तचेतसः", "gram": "nom. pl. m. comp.", "es": "con la mente unida", "ref": "yukta", "analisis": "yukta (unido, disciplinado) + cetas (mente, pensamiento)"}], "nota": "<p><em>Sa-adhibhūta-adhidaivam</em> y <em>sa-adhiyajñam</em>: el prefijo <em>sa-</em> significa «con, junto con». Los tres términos, como los dos del verso anterior, no se definen aquí: Arjuna pedirá su explicación al comienzo del capítulo siguiente (<a class=\"vref\" href=\"capitulo-08.html#v1\" data-v=\"8.1\">8.1</a>–<a class=\"vref\" href=\"capitulo-08.html#v2\" data-v=\"8.2\">8.2</a>), y Kṛṣṇa la dará en <a class=\"vref\" href=\"capitulo-08.html#v3\" data-v=\"8.3\">8.3</a>–<a class=\"vref\" href=\"capitulo-08.html#v4\" data-v=\"8.4\">8.4</a>. <em>Prayāṇa-kāla</em>: literalmente «la hora de la partida», la muerte. <em>Yukta-cetas</em>: «de mente unida».</p>", "interp": [{"titulo": "Siete preguntas", "html": "<p>El capítulo termina con una serie de términos sin explicar: brahman, lo relativo al sí-mismo y la acción (<a class=\"vref\" href=\"capitulo-07.html#v29\" data-v=\"7.29\">7.29</a>); lo relativo a los seres, a los dioses y al sacrificio, y la hora de la muerte. Son exactamente las siete preguntas con que <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a> abre el capítulo 8 (<a class=\"vref\" href=\"capitulo-08.html#v1\" data-v=\"8.1\">8.1</a>–<a class=\"vref\" href=\"capitulo-08.html#v2\" data-v=\"8.2\">8.2</a>). La Gītā encadena así los dos capítulos, y la última de las siete, cómo se conoce a Kṛṣṇa en la hora de la muerte, será el tema del siguiente: lo que se recuerda al morir determina adónde se va (<a class=\"vref\" href=\"capitulo-08.html#v5\" data-v=\"8.5\">8.5</a>–<a class=\"vref\" href=\"capitulo-08.html#v6\" data-v=\"8.6\">8.6</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "conocerlo-por-entero"}], "ensenanzas": [{"id": "las-dos-naturalezas", "desde": 4, "hasta": 6, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Las dos naturalezas de Kṛṣṇa", "resumen": "<p>Kṛṣṇa tiene dos naturalezas. La inferior está dividida en ocho: los cinco elementos —tierra, agua, fuego, aire y espacio— y las tres facultades internas —mente, entendimiento y sentido del yo—. La superior es la viviente, la que sostiene el mundo. Todos los seres nacen de las dos, y por eso Kṛṣṇa es el origen y la disolución del universo entero. La materia y la vida, que el Sāṅkhya oponía como dos principios, son aquí dos aspectos de un mismo dueño.</p>"}, {"id": "ensartado-en-mi", "desde": 7, "hasta": 7, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Todo ensartado en Kṛṣṇa como perlas en un hilo", "resumen": "<p>No hay nada más alto que Kṛṣṇa, y todo lo que existe está ensartado en él como las perlas en un hilo. El hilo no se ve, pero es lo que hace de las cuentas un collar: Kṛṣṇa no es una cosa más del mundo, sino aquello que lo mantiene unido. Los versos siguientes muestran ese hilo en cada cosa: el sabor del agua, la luz del sol y de la luna, la sílaba oṃ.</p>"}, {"id": "lo-esencial-de-cada-cosa", "desde": 8, "hasta": 11, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Lo esencial de cada cosa: «yo soy el sabor en el agua»", "resumen": "<p>Kṛṣṇa enseña a reconocerlo en lo que cada cosa tiene de más propio y de mejor: el sabor del agua, la luz del sol y de la luna, la sílaba <a class=\"t\" href=\"glosario.html#om\" data-t=\"om\">oṃ</a> en los <a class=\"t\" href=\"glosario.html#veda\" data-t=\"veda\">Vedas</a>, el sonido en el espacio, el olor puro de la tierra, la vida en los seres, la <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridad</a> en los ascetas, el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> en los que entienden. Es la <a class=\"t\" href=\"glosario.html#bija\" data-t=\"bija\">semilla</a> eterna de todos los seres, la fuerza libre de deseo y de apego, y el deseo que no se opone al <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a>. No hay que buscarlo fuera de las cosas, sino en su esencia; el capítulo 10 desarrollará esta manera de verlo.</p>"}, {"id": "yo-no-estoy-en-ellos", "desde": 12, "hasta": 12, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "«Yo no estoy en ellos: ellos están en mí»", "resumen": "<p>Todos los estados que nacen de las tres <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a> proceden de Kṛṣṇa, pero él no está en ellos: ellos están en él. Que sea la esencia de las cosas no lo encierra en ellas ni lo hace depender de ellas. Es la primera formulación de una idea que el capítulo 9 llevará a la paradoja (<a class=\"vref\" href=\"capitulo-09.html#v4\" data-v=\"9.4\">9.4</a>–<a class=\"vref\" href=\"capitulo-09.html#v5\" data-v=\"9.5\">9.5</a>).</p>"}, {"id": "cruzar-la-maya", "desde": 13, "hasta": 15, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "La māyā, que sólo se cruza con el refugio", "resumen": "<p>Los estados que producen las tres <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a> forman una <a class=\"t\" href=\"glosario.html#maya\" data-t=\"maya\">māyā</a> divina que vela a Kṛṣṇa: el mundo ve los efectos y no reconoce al que está más allá de ellos. Esa māyā es difícil de cruzar por las propias fuerzas; la cruzan quienes se <a class=\"t\" href=\"glosario.html#prapatti\" data-t=\"prapatti\">refugian</a> sólo en Kṛṣṇa (<a class=\"vref\" href=\"capitulo-07.html#v14\" data-v=\"7.14\">7.14</a>). No lo hacen los que, privados de conocimiento por ella, se han acogido a la condición <a class=\"t\" href=\"glosario.html#asura\" data-t=\"asura\">demoníaca</a>.</p>"}, {"id": "las-cuatro-clases-de-devotos", "desde": 16, "hasta": 19, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Las cuatro clases de devotos y el sabio", "resumen": "<p>Acuden a Kṛṣṇa el afligido, el que desea conocer, el que busca riqueza y el <a class=\"t\" href=\"glosario.html#jnanin\" data-t=\"jnanin\">sabio</a>. Los cuatro son nobles, pero el sabio, siempre unido y de devoción única, es el más querido: Kṛṣṇa lo tiene por su propio ser. Llegar a él lleva muchos nacimientos, y culmina en la convicción de que «Vāsudeva es todo» (<a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a>).</p>"}, {"id": "la-fe-en-otros-dioses", "desde": 20, "hasta": 23, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "La fe en otros dioses: quién la sostiene y adónde lleva", "resumen": "<p>Kṛṣṇa explica el culto a otras divinidades sin condenarlo. Quien tiene deseos acude a la divinidad que los satisface, según su propia naturaleza (<a class=\"vref\" href=\"capitulo-07.html#v20\" data-v=\"7.20\">7.20</a>); sea cual sea la forma que adore, es Kṛṣṇa quien hace firme su fe (<a class=\"vref\" href=\"capitulo-07.html#v21\" data-v=\"7.21\">7.21</a>), y aunque el fruto le llegue por medio de esa divinidad, quien lo concede es él (<a class=\"vref\" href=\"capitulo-07.html#v22\" data-v=\"7.22\">7.22</a>). El límite está en el fruto: tiene fin, porque cada cual llega a lo que adora; los que sacrifican a los dioses van a los dioses, los devotos de Kṛṣṇa van a él (<a class=\"vref\" href=\"capitulo-07.html#v23\" data-v=\"7.23\">7.23</a>).</p>"}, {"id": "el-senor-velado", "desde": 24, "hasta": 26, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El Señor velado: por qué no se lo reconoce", "resumen": "<p>Si Kṛṣṇa está en todo, ¿por qué no se lo ve? Los faltos de entendimiento lo toman por algo que antes no era manifiesto y ha llegado a manifestarse, sin conocer su estado supremo e imperecedero (<a class=\"vref\" href=\"capitulo-07.html#v24\" data-v=\"7.24\">7.24</a>). No se muestra a todos: lo vela su <a class=\"t\" href=\"glosario.html#yoga-maya\" data-t=\"yoga-maya\">yoga-māyā</a>, y el mundo extraviado no lo reconoce como no nacido e imperecedero (<a class=\"vref\" href=\"capitulo-07.html#v25\" data-v=\"7.25\">7.25</a>). Él conoce a todos los seres, pasados, presentes y futuros; a él nadie lo conoce (<a class=\"vref\" href=\"capitulo-07.html#v26\" data-v=\"7.26\">7.26</a>). El conocimiento de Kṛṣṇa no es, por eso, uno más entre otros: el capítulo entero trata de cómo se llega a él.</p>"}, {"id": "el-extravio-de-los-opuestos", "desde": 27, "hasta": 28, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El extravío de los opuestos y su fin", "resumen": "<p>Todos los seres nacen en la confusión que engendran el deseo y la aversión: la de vivir entre pares de opuestos, lo grato y lo ingrato. Salen de ella los que, por sus obras meritorias, han agotado el <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a>; libres de ese <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extravío</a>, adoran a Kṛṣṇa con firmeza.</p>"}, {"id": "conocerlo-por-entero", "desde": 29, "hasta": 30, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Conocerlo por entero, también en la hora de la muerte", "resumen": "<p>Quien se acoge a Kṛṣṇa para librarse de la vejez y de la muerte llega a conocer <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, <a class=\"t\" href=\"glosario.html#adhyatma\" data-t=\"adhyatma\">lo relativo al sí-mismo</a> y toda la acción; y quien lo conoce junto con lo relativo a los seres, a los dioses y al sacrificio lo conoce también al morir. Los términos quedan sin definir: el capítulo 8 empieza preguntando por ellos.</p>"}]};
